            tip_type_Val_1 = tip_Parameter_Type1_Val(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type1_Name));
            if app.IP_CheckBox.Value
                tip_type_ip_1 = contains(tip_type_Name_1(:,1), 'IL');
                tip_type_Val_1(tip_type_ip_1,1) = {'17'};
            end
