        % Code that executes after component creation
        function startupFcn(app)
            clc;
            app.Stage_Table.Data = zeros(19,15);
            app.Stator_Blade_Table.Data = zeros(19,7);
            app.Rotor_Blade_Table.Data = zeros(19,6);
            app.Interstage_Parameter_Table.Data = zeros(1,16);
            app.Pre_Setting_Table.Data = zeros(19,4);
            app.Filet_A_EditField.Value = 0;
            app.Filet_B_EditField.Value = 0;
            app.Filet_R_EditField.Value = 0;
            fid = fopen('Doosan_Interstage_Seal_Parameter_251105.csv','r','native','UTF-8');
            f = fread(fid,'*char')';
            fclose(fid);
            s_str = split(f,'#');
            s_str([1,2,3,4,6],:) = [];
            app.prameter_name = s_str(1,:);
            app.prameter_name = strip(split(app.prameter_name ,','));
            app.prameter_name (1,:) = [];
            prameter_val = s_str(2,:);
            prameter_val = extractAfter(prameter_val , "DP");
            prameter_val = strip(split(prameter_val ,','));
            prameter_val(1,:) = [];
            clear fid f s_str;
            New_parameter_name_row = {};
            for i = 1:length(app.prameter_name)
                parameter_name_row = app.prameter_name{i};
                parameter_name_index = strfind(parameter_name_row, '-');
                Start_Index = parameter_name_index + 2;
                parameter_name_row = strtrim(parameter_name_row(Start_Index:end));
                New_parameter_name_row{end+1,1} = parameter_name_row;
