            if contains(env_check,'TurboGrid','IgnoreCase',true)
            else
                [Zero, Env] = system('set');
                Env = splitlines(Env);
                New_Env = {};
                for i = 1:length(Env)
                    Env_row = Env{i};
                    if contains(Env_row, 'AWP_ROOT', 'IgnoreCase', true)
                        Env_Index = strfind(Env_row, '=');
                        Start_Index = Env_Index + 1;
                        Env_row = strtrim(Env_row(Start_Index:end));
                        New_Env{end+1,1} = Env_row;
                    end
                end

                for i = 1:length(New_Env)
                    ans_path = New_Env{i};

                    cfx5root = fullfile(ans_path, 'CFX');
                    cfx5bindir = fullfile(cfx5root, 'bin');
