                    cfx5libdir = fullfile(cfx5root, 'lib', cfx5os);
                    turboGridExecDir = fullfile(turboGridBin, cfx5os);
                    ansysCommonRoot = fullfile(ans_path, 'commonfiles');
                    cfxToolsRoot = fullfile(ans_path, 'Shared');
                    xercesPath = fullfile(ans_path, 'Tools', 'xerces', 'win-amd64');

                    perlVersion = '5.34.0';
                    perlInstallArch = 'MSWin32-x64-perlio';
                    cfx5perl = fullfile(cfxToolsRoot, ['perl-' perlVersion], 'bin', perlInstallArch);

                    currentPath = getenv('PATH');
                    newPaths = {cfx5bindir,cfx5execdir,cfx5libdir,turboGridBin,turboGridExecDir,xercesPath,cfx5perl,...
                        fullfile(ansysCommonRoot, 'CFX', 'bin'),fullfile(cfxToolsRoot, 'share', 'bin')};

                    for j = 1:length(newPaths)
                        if contains(newPaths{i}, ' ')
                            newPaths{j} = ['"' newPaths{j} '"'];
                        end
                    end

                    newPathStr = strjoin(newPaths, ';');

                    setenv('PATH', [currentPath ';' newPathStr]);
                    setenv('TMP', tempdir);
                    setenv('TEMP', tempdir);
                    %                 setenv('CFX5ROOT', cfx5root);
                    %                 setenv('CFX5BINDIR', cfx5bindir);
                    %                 setenv('CFX5OS', cfx5os);
                    %                 setenv('ANSYSOS', ansysos);

                end

                perlLibDir = fullfile(cfxToolsRoot, ['perl-' perlVersion], 'lib');
                perl5Lib = [fullfile(perlLibDir, perlVersion, perlInstallArch), ';', fullfile(perlLibDir, perlVersion), ';', ...
                    fullfile(perlLibDir, 'site_perl'), ';', fullfile(perlLibDir, 'site_perl', perlVersion, perlInstallArch)];
                setenv('PERL5LIB', perl5Lib);

                if contains(Env_row, 'windir', 'IgnoreCase', true)
                    Env_Index = strfind(Env_row, '=');
                    Start_Index = Env_Index + 1;
                    Env_row = strtrim(Env_row(Start_Index:end));
                    window_dir = Env_row;
                end

            end



