                    New_EditField.BackgroundColor = [0.9412 0.9412 0.9412];
                    New_EditField.Position = [11 new_edit_y 116 70];
                    New_EditField.Editable = 'off';

                    new_dropdown_y = 26 + (app.Stage_Number - i) * 110;
