                    %New_tip_extraction.FontWeight = 'bold';
                    New_tip_extraction.Position = [137 new_tip_extraction_y 67 22];
                    New_tip_extraction.Text = 'Extraction';

                    new_tip_checkbox_y = 26 + (app.Stage_Number - i) * 110;
                    new_tip_checkbox = uicheckbox(app.Tip_Seal_Parameter_Table_Panel);
                    new_tip_checkbox.FontSize = 14;
                    new_tip_checkbox.Text = '';
                    new_tip_checkbox.Position = [137 new_tip_checkbox_y 44 22];
                    new_tip_checkbox.Tag = ['Tip_Seal_Checkbox_', num2str(app.Tip_TableCounter)];

                    new_tip_textarea_y = 26 + (app.Stage_Number - i) * 110;
                    new_tip_textarea = uieditfield(app.Tip_Seal_Parameter_Table_Panel, 'numeric');
                    new_tip_textarea.FontSize = 14;
                    new_tip_textarea.Editable = 'on';
                    new_tip_textarea.Position = [157 new_tip_textarea_y 44 22];
                    new_tip_textarea.Tag = ['Tip_Seal_text_', num2str(app.Tip_TableCounter)];

                    app.Tip_TableCounter = app.Tip_TableCounter + 1;
                end
                app.TableCounter = 1;
                app.Tip_TableCounter = 1;
                app.Data_Button.Enable = 'On';
                app.Blade_Offset_Button.Enable = 'On';
                app.Range_Button.Enable = 'On';
                app.Blade_Mesh_TextAreaLabel.Enable = 'On';
                app.Blade_Only_CheckBox.Enable = 'On';
                app.Blade_Mesh_Group.Enable = 'On';
                %app.Interstage_FileButton.Enable = 'On';
                %app.Tip_FileButton.Enable = 'On';
                app.End_Stage = app.Stage_Number;
                app.Start_Stage = 1;

                Data_File_Folder = [app.path, 'Data File'];
                mkdir(Data_File_Folder);

            catch ME
                uialert(app.UIFigure, ['데이터 읽기 실패: ' ME.message], 'Data Reading Error');
            end

            figure(app.UIFigure);
        end

