        % Button pushed function: Data_Button
        function Data_ButtonPushed(app, event)
            try
                %app.Mesh_Button.Enable = 'On';
                %app.Tip_DataButton.Enable = 'On';
                %app.Interstage_DataButton.Enable = 'On';
                Version_Check = app.CFX_Version_DropDown.Value;
                Stator_Blade_Data = app.Stator_Blade_Table.Data;
                Rotor_Blade_Data = app.Rotor_Blade_Table.Data;
                Stage_Data = app.Stage_Table.Data;
                a_Data = app.Filet_A_EditField.Value;
                b_Data = app.Filet_B_EditField.Value;
                app.r_Data = app.Filet_R_EditField.Value;

                Stator_Blade_Data = cell2table(Stator_Blade_Data);
                Rotor_Blade_Data = cell2table(Rotor_Blade_Data);
                Stage_Data = cell2table(Stage_Data);

                old_Stator_Blade_column = Stator_Blade_Data.Properties.VariableNames;
                old_Rotor_Blade_column = Rotor_Blade_Data.Properties.VariableNames;
                old_Stage_column = Stage_Data.Properties.VariableNames;

                Stator_Blade_Data = renamevars(Stator_Blade_Data, old_Stator_Blade_column,["N","Dr","Dh","L","Mih","Mis","xTe"]);
                Rotor_Blade_Data = renamevars(Rotor_Blade_Data, old_Rotor_Blade_column,["N","Dr","Dh","L","Mih","Mis"]);
                Stage_Data = renamevars(Stage_Data, old_Stage_column,["PrevStDist","NzlRW","NzlROTe","NzlTW","NzlTOTe","BckRW","BckBldEx","BckShW","BckShEx","AxGap","TDG","SLdist","DX13","PrevStDG","Reynolds"]);

                Stator_N = Stator_Blade_Data.N;
                Stator_Dh = Stator_Blade_Data.Dh;
                Stator_L = Stator_Blade_Data.L;
                Stator_Mih = Stator_Blade_Data.Mih;
                Stator_Mis = Stator_Blade_Data.Mis;
                Stator_xTe = Stator_Blade_Data.xTe;

                Rotor_N = Rotor_Blade_Data.N;
                Rotor_Dh = Rotor_Blade_Data.Dh;
                Rotor_L = Rotor_Blade_Data.L;
                Rotor_Mih = Rotor_Blade_Data.Mih;
                Rotor_Mis = Rotor_Blade_Data.Mis;

                Stage_PrevStDist = Stage_Data.PrevStDist;
                app.Stage_NzlRW = Stage_Data.NzlRW;
                Stage_NzlROTe = Stage_Data.NzlROTe;
                app.Stage_NzlTW = Stage_Data.NzlTW;
                Stage_NzlTOTe = Stage_Data.NzlTOTe;
                app.Stage_BckRW = Stage_Data.BckRW;
                Stage_BckBldEx = Stage_Data.BckBldEx;
                app.Stage_BckShW = Stage_Data.BckShW;
                Stage_BckShEx = Stage_Data.BckShEx;
                Stage_AxGap = Stage_Data.AxGap;
                Stage_Reynolds = Stage_Data.Reynolds;

                Stator_N = cellfun(@str2double, Stator_N);
                Stator_Dh = cellfun(@str2double, Stator_Dh);
                Stator_L = cellfun(@str2double, Stator_L);
                Stator_Mih = cellfun(@str2double, Stator_Mih);
                Stator_Mis = cellfun(@str2double, Stator_Mis);
                Stator_xTe = cellfun(@str2double, Stator_xTe);

                Rotor_N = cellfun(@str2double, Rotor_N);
                Rotor_Dh = cellfun(@str2double, Rotor_Dh);
                Rotor_L = cellfun(@str2double, Rotor_L);
                Rotor_Mih = cellfun(@str2double, Rotor_Mih);
                Rotor_Mis = cellfun(@str2double, Rotor_Mis);

                Stage_PrevStDist = cellfun(@str2double, Stage_PrevStDist);
                app.Stage_NzlRW = cellfun(@str2double, app.Stage_NzlRW);
                Stage_NzlROTe = cellfun(@str2double, Stage_NzlROTe);
                app.Stage_NzlTW = cellfun(@str2double, app.Stage_NzlTW);
                Stage_NzlTOTe = cellfun(@str2double, Stage_NzlTOTe);
                app.Stage_BckRW = cellfun(@str2double, app.Stage_BckRW);
                Stage_BckBldEx = cellfun(@str2double, Stage_BckBldEx);
                app.Stage_BckShW = cellfun(@str2double, app.Stage_BckShW);
                Stage_BckShEx = cellfun(@str2double, Stage_BckShEx);
                Stage_AxGap = cellfun(@str2double, Stage_AxGap);
                Stage_Reynolds = cellfun(@str2double, Stage_Reynolds);

                Old_Stage_PrevStDist = Stage_PrevStDist;
                for a = 1:app.Stage_Number
                    rowRange =Old_Stage_PrevStDist(1:a);
                    %rowRange = cell2mat(rowRange);
                    sum_data = sum(rowRange(:));
                    New_Stage_PrevStDist{a, 1} = sum_data;
                end
                Stage_PrevStDist = cell2mat(New_Stage_PrevStDist);

                format long g;

                blade_path = replace(app.path, "\", "/");
                for h = app.Start_Stage : app.End_Stage
                    nzl_filename = sprintf('nzl%02d_blade.curve', h);

                    if app.Blade_Offset_Button.Value == true
                        nzl_filename = sprintf('nzl%02d_blade_offset.curve', h);
                    end

                    Blade_File_Path = fullfile(blade_path, nzl_filename);
                    nzl_blade_curve = fileread(Blade_File_Path);

                    if app.HP_CheckBox.Value == true
                        New_nzl_filename = sprintf('HP_nzl%02d_blade.curve', h);
                    elseif app.IP_CheckBox.Value == true
                        New_nzl_filename = sprintf('IP_nzl%02d_blade.curve', h);
                    end

                    if app.Blade_Offset_Button.Value == true
                        if app.HP_CheckBox.Value == true
                            New_nzl_filename = sprintf('HP_nzl%02d_blade_offset.curve', h);
                        elseif app.IP_CheckBox.Value == true
                            New_nzl_filename = sprintf('IP_nzl%02d_blade_offset.curve', h);
                        end
                    end

                    New_Blade_File_Path = fullfile(blade_path, New_nzl_filename);
                    fid = fopen(New_Blade_File_Path, 'w');
                    sections = strsplit(nzl_blade_curve, '#');
                    for k = 2:length(sections)
                        section = strtrim(sections{k});
                        if ~isempty(nzl_blade_curve)
                            fprintf(fid, '#\n');
                            data = textscan(section, '%f %f %f', 'Delimiter', ' ', 'MultipleDelimsAsOne', true);
                            x_values = data{1,1};
                            if app.Minus_CheckBox.Value == true
                                x_values = -abs(x_values);
                            elseif app.Plus_CheckBox.Value == true
                                x_values = abs(x_values);
                            end
                            y_values = data{1,2};
                            z_values = data{1,3};
                            for z = 1:size(z_values)
                                fprintf(fid, '  %.13f    %.13f    %.13f\n', x_values(z,1), y_values(z,1), z_values(z,1));
                            end
                            fprintf(fid, '\n');
                        end
                    end

                    bck_filename = sprintf('bck%02d_blade.curve', h);

                    if app.Blade_Offset_Button.Value == true
                        bck_filename = sprintf('bck%02d_blade_offset.curve', h);
                    end

                    Blade_File_Path = fullfile(blade_path, bck_filename);
                    bck_blade_curve = fileread(Blade_File_Path);

                    if app.HP_CheckBox.Value == true
                        New_bck_filename = sprintf('HP_bck%02d_blade.curve', h);
                    elseif app.IP_CheckBox.Value == true
                        New_bck_filename = sprintf('IP_bck%02d_blade.curve', h);
                    end

                    if app.Blade_Offset_Button.Value == true
                        if app.HP_CheckBox.Value == true
                            New_bck_filename = sprintf('HP_bck%02d_blade_offset.curve', h);
                        elseif app.IP_CheckBox.Value == true
                            New_bck_filename = sprintf('IP_bck%02d_blade_offset.curve', h);
                        end
                    end

                    New_Blade_File_Path = fullfile(blade_path, New_bck_filename);
                    fid = fopen(New_Blade_File_Path, 'w');
                    sections = strsplit(bck_blade_curve, '#');
                    for k = 2:length(sections)
                        section = strtrim(sections{k});
                        if ~isempty(bck_blade_curve)
                            fprintf(fid, '#\n');
                            data = textscan(section, '%f %f %f', 'Delimiter', ' ', 'MultipleDelimsAsOne', true);
                            x_values = data{1,1};
                            if app.Minus_CheckBox.Value == true
                                x_values = -abs(x_values);
                            elseif app.Plus_CheckBox.Value == true
                                x_values = abs(x_values);
                            end
                            y_values = data{1,2};
                            z_values = data{1,3};
                            for z = 1:size(z_values)
                                fprintf(fid, '  %.13f    %.13f    %.13f\n', x_values(z,1), y_values(z,1), z_values(z,1));
                            end
                            fprintf(fid, '\n');
                        end
                    end
                end
                fclose('all');

                if app.Minus_CheckBox.Value

                    app.hub_nz_in_x = ( Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap - app.Stage_NzlRW ) * -1 ;
                    hub_nz_in_y = zeros(app.Stage_Number, 1);
                    app.hub_nz_in_z = (Stator_Dh / 2) - (Stage_NzlROTe + Stator_xTe).*tand(Stator_Mih);
                    hub_nz_in = [app.hub_nz_in_x, hub_nz_in_y, app.hub_nz_in_z];

                    app.hub_nz_out_x = ( Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap ) * -1 ;
                    hub_nz_out_y = zeros(app.Stage_Number, 1);
                    app.hub_nz_out_z = (Stator_Dh / 2) + (app.Stage_NzlRW - (Stage_NzlROTe + Stator_xTe)).*tand(Stator_Mih);
                    hub_nz_out = [app.hub_nz_out_x, hub_nz_out_y, app.hub_nz_out_z];

                    shroud_nz_in_x_1 = ( Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap - Stage_NzlROTe + Stage_NzlTOTe - app.Stage_NzlTW ) * -1;
                    shroud_nz_in_y_1 = zeros(app.Stage_Number, 1);
                    shroud_nz_in_z_1 = (Stator_Dh / 2) + Stator_L - (app.Stage_NzlTW - (Stage_NzlTOTe + Stator_xTe)).*tand(Stator_Mis);
                    shroud_nz_in_1 = [shroud_nz_in_x_1, shroud_nz_in_y_1, shroud_nz_in_z_1];

                    app.shroud_nz_in_x_r = ( Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap - Stage_NzlROTe + Stage_NzlTOTe - app.Stage_NzlTW ) * -1 + ( (app.r_Data * cosd(Stator_Mis) ./ tand(45 - (Stator_Mis / 2))) ) * -1;
                    shroud_nz_in_y = zeros(app.Stage_Number, 1);
                    app.shroud_nz_in_z_r = ( (Stator_Dh / 2) + Stator_L - (app.Stage_NzlTW - (Stage_NzlTOTe + Stator_xTe)).*tand(Stator_Mis) ) + ( (app.r_Data * sind(Stator_Mis) ./ tand(45 - (Stator_Mis / 2))) );
                    shroud_nz_in_r = [app.shroud_nz_in_x_r, shroud_nz_in_y, app.shroud_nz_in_z_r];

                    app.shroud_nz_out_x = ( Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap - Stage_NzlROTe + Stage_NzlTOTe )* -1;
                    shroud_nz_out_y = zeros(app.Stage_Number, 1);
                    app.shroud_nz_out_z = (Stator_Dh / 2) + Stator_L + (Stage_NzlTOTe + Stator_xTe).*tand(Stator_Mis);
                    shroud_nz_out = [app.shroud_nz_out_x, shroud_nz_out_y, app.shroud_nz_out_z];

                    app.hub_bc_in_x = ( Stage_PrevStDist - (app.Stage_BckRW / 2) ) * -1;
                    hub_bc_in_x_r = ( Stage_PrevStDist - (app.Stage_BckRW / 2) ) * -1 + ( ceil(app.Stage_BckRW * a_Data) ) * -1;
                    hub_bc_in_y = zeros(app.Stage_Number, 1);
                    app.hub_bc_in_z = (Rotor_Dh / 2) - ((app.Stage_BckRW / 2) + (Stage_BckBldEx)).*tand(Rotor_Mih);
                    app.hub_bc_in_z_r = (Rotor_Dh / 2) - ((app.Stage_BckRW / 2) + (Stage_BckBldEx)).*tand(Rotor_Mih) - ceil(app.Stage_BckRW * a_Data )* b_Data ;
                    hub_bc_in = [app.hub_bc_in_x, hub_bc_in_y, app.hub_bc_in_z_r];
                    hub_bc_in_r = [hub_bc_in_x_r, hub_bc_in_y, app.hub_bc_in_z];

                    hub_bc_round_N = abs((app.hub_bc_in_x - hub_bc_in_x_r)/0.2);

                    app.hub_bc_out_x = ( Stage_PrevStDist + (app.Stage_BckRW / 2) ) * -1;
                    hub_bc_out_y = zeros(app.Stage_Number, 1);
                    app.hub_bc_out_z =(Rotor_Dh / 2) + ((app.Stage_BckRW / 2) - (Stage_BckBldEx)).*tand(Rotor_Mih);
                    hub_bc_out = [app.hub_bc_out_x, hub_bc_out_y, app.hub_bc_out_z];

                    app.shroud_bc_in_x = ( Stage_PrevStDist + Stage_BckBldEx - Stage_BckShEx - (app.Stage_BckShW / 2)) *-1;
                    shroud_bc_in_y = zeros(app.Stage_Number, 1);
                    app.shroud_bc_in_z = (Rotor_Dh / 2) + Rotor_L - ((app.Stage_BckRW / 2) + Stage_BckBldEx).*tand(Rotor_Mis);
                    shroud_bc_in = [app.shroud_bc_in_x, shroud_bc_in_y, app.shroud_bc_in_z];

                    app.shroud_bc_out_x = ( Stage_PrevStDist + Stage_BckBldEx - Stage_BckShEx + (app.Stage_BckShW / 2)) *-1;
                    shroud_bc_out_y = zeros(app.Stage_Number, 1);
                    app.shroud_bc_out_z =(Rotor_Dh / 2) + Rotor_L + ((app.Stage_BckRW / 2) - Stage_BckBldEx).*tand(Rotor_Mis);
                    shroud_bc_out = [app.shroud_bc_out_x, shroud_bc_out_y, app.shroud_bc_out_z];

                else

                    app.hub_nz_in_x = Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap - app.Stage_NzlRW;
                    hub_nz_in_y = zeros(app.Stage_Number, 1);
                    app.hub_nz_in_z = (Stator_Dh / 2) - (Stage_NzlROTe + Stator_xTe).*tand(Stator_Mih);
                    hub_nz_in = [app.hub_nz_in_x, hub_nz_in_y, app.hub_nz_in_z];

                    app.hub_nz_out_x = Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap;
                    hub_nz_out_y = zeros(app.Stage_Number, 1);
                    app.hub_nz_out_z = (Stator_Dh / 2) + (app.Stage_NzlRW - (Stage_NzlROTe + Stator_xTe)).*tand(Stator_Mih);
                    hub_nz_out = [app.hub_nz_out_x, hub_nz_out_y, app.hub_nz_out_z];

                    shroud_nz_in_x_1 = Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap - Stage_NzlROTe + Stage_NzlTOTe - app.Stage_NzlTW;
                    shroud_nz_in_y_1 = zeros(app.Stage_Number, 1);
                    shroud_nz_in_z_1 = (Stator_Dh / 2) + Stator_L - (app.Stage_NzlTW - (Stage_NzlTOTe + Stator_xTe)).*tand(Stator_Mis);
                    shroud_nz_in_1 = [shroud_nz_in_x_1, shroud_nz_in_y_1, shroud_nz_in_z_1];

                    app.shroud_nz_in_x_r = Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap - Stage_NzlROTe + Stage_NzlTOTe - app.Stage_NzlTW + (app.r_Data * cosd(Stator_Mis) ./ tand(45 - (Stator_Mis / 2)));
                    shroud_nz_in_y = zeros(app.Stage_Number, 1);
                    app.shroud_nz_in_z_r = (Stator_Dh / 2) + Stator_L - (app.Stage_NzlTW - (Stage_NzlTOTe + Stator_xTe)).*tand(Stator_Mis) + (app.r_Data * sind(Stator_Mis) ./ tand(45 - (Stator_Mis / 2)));
                    shroud_nz_in_r = [app.shroud_nz_in_x_r, shroud_nz_in_y, app.shroud_nz_in_z_r];

                    app.shroud_nz_out_x = Stage_PrevStDist - (app.Stage_BckRW / 2) - Stage_AxGap - Stage_NzlROTe + Stage_NzlTOTe;
                    shroud_nz_out_y = zeros(app.Stage_Number, 1);
                    app.shroud_nz_out_z = (Stator_Dh / 2) + Stator_L + (Stage_NzlTOTe + Stator_xTe).*tand(Stator_Mis);
                    shroud_nz_out = [app.shroud_nz_out_x, shroud_nz_out_y, app.shroud_nz_out_z];

                    app.hub_bc_in_x = Stage_PrevStDist - (app.Stage_BckRW / 2);
                    hub_bc_in_x_r = Stage_PrevStDist - (app.Stage_BckRW / 2) + ceil(app.Stage_BckRW .* a_Data);
                    hub_bc_in_y = zeros(app.Stage_Number, 1);
                    app.hub_bc_in_z = (Rotor_Dh / 2) - ((app.Stage_BckRW / 2) + (Stage_BckBldEx)).*tand(Rotor_Mih);
                    app.hub_bc_in_z_r = (Rotor_Dh / 2) - ((app.Stage_BckRW / 2) + (Stage_BckBldEx)).*tand(Rotor_Mih) - ceil(app.Stage_BckRW * a_Data )* b_Data ;
                    hub_bc_in = [app.hub_bc_in_x, hub_bc_in_y, app.hub_bc_in_z_r];
                    hub_bc_in_r = [hub_bc_in_x_r, hub_bc_in_y, app.hub_bc_in_z];

                    hub_bc_round_N = abs((app.hub_bc_in_x - hub_bc_in_x_r)/0.2);

                    app.hub_bc_out_x = Stage_PrevStDist + (app.Stage_BckRW / 2);
                    hub_bc_out_y = zeros(app.Stage_Number, 1);
                    app.hub_bc_out_z =(Rotor_Dh / 2) + ((app.Stage_BckRW / 2) - (Stage_BckBldEx)).*tand(Rotor_Mih);
                    hub_bc_out = [app.hub_bc_out_x, hub_bc_out_y, app.hub_bc_out_z];

                    app.shroud_bc_in_x = Stage_PrevStDist + Stage_BckBldEx - Stage_BckShEx - (app.Stage_BckShW / 2);
                    shroud_bc_in_y = zeros(app.Stage_Number, 1);
                    app.shroud_bc_in_z = (Rotor_Dh / 2) + Rotor_L - ((app.Stage_BckRW / 2) + Stage_BckBldEx).*tand(Rotor_Mis);
                    shroud_bc_in = [app.shroud_bc_in_x, shroud_bc_in_y, app.shroud_bc_in_z];

                    app.shroud_bc_out_x = Stage_PrevStDist + Stage_BckBldEx - Stage_BckShEx + (app.Stage_BckShW / 2);
                    shroud_bc_out_y = zeros(app.Stage_Number, 1);
