                        inlet_x = min(abs(app.hub_bc_in_x(a, :)/1000),abs(app.shroud_bc_in_x(a, :)/1000));
                        outlet_x = max(abs(app.hub_bc_out_x(a, :)/1000),abs(app.shroud_bc_out_x(a, :)/1000));

                        inlet_z = num2str((app.hub_bc_in_z_r(a, :)/1000) * 0.2 + (app.shroud_bc_in_z(a, :)/1000) * 0.8) ;
                        outlet_z = num2str((app.hub_bc_out_z(a, :)/1000) * 0.2 + (app.shroud_bc_out_z(a, :)/1000) * 0.8) ;

                        bc_tst = replace(bc_tst,"inlet_point_x", num2str(inlet_x));
                        bc_tst = replace(bc_tst,"inlet_point_z", inlet_z);
                        bc_tst = replace(bc_tst,"outlet_point_x", num2str(outlet_x));
                        bc_tst = replace(bc_tst,"outlet_point_z", outlet_z);

                        bc_tst_File = fopen('bck_tst.txt','w','native','UTF-8');
                        fprintf(bc_tst_File, '%s', bc_tst);

                        fclose('all');

                        movefile('nzl_tst.txt', fullfile(app.path, sprintf('nzl_%02d.tst', a)));
                        movefile('bck_tst.txt', fullfile(app.path, sprintf('bck_%02d.tst', a)));

                    end
                end

                waitbar(3/4,status_bar,'Generating tse File...');
                if getappdata(status_bar, 'canceling')
                    msgbox('작업이 취소되었습니다.', '작업 취소', 'warn');
