                    fprintf(fid, '오류 발생 시간: %s\n', datestr(now));
                    fprintf(fid, '오류 메시지: %s\n\n', ME.message);

                    fprintf(fid, '스택 추적:\n');
                    for k = 1:length(ME.stack)
                        fprintf(fid, 'File: %s\n', ME.stack(k).file);
                        fprintf(fid, 'Name: %s\n', ME.stack(k).name);
                        fprintf(fid, 'Line: %d\n\n', ME.stack(k).line);
                    end

                    fprintf(fid, '시스템 정보:\n');
                    fprintf(fid, 'MATLAB 버전: %s\n', version);
                    fprintf(fid, '운영 체제: %s\n', computer);

                    fclose(fid);

                    errordlg(...
                        sprintf('오류가 발생했습니다. 자세한 내용은 다음 로그 파일을 확인하세요:\n%s', logFilePath), '오류 발생');
                end
            end

        end

        % Button pushed function: Mesh_Button
        function Mesh_ButtonPushed(app, event)
            try
                app.path = replace(app.path, "\", "/");
                ans_path = {};
                Version_Check = app.CFX_Version_DropDown.Value;
                Work =  app.End_Stage - app.Start_Stage;
                Work_count = 0;

                [Zero, Env] = system('set');
                Env = splitlines(Env);
                New_Env = {};
                for i = 1:length(Env)
                    Env_row = Env{i};
                    if contains(Env_row, 'AWP_ROOT', 'IgnoreCase', true)
                        Env_Index = strfind(Env_row, '=');
                        Start_Index = Env_Index + 1;
                        Env_row = strtrim(Env_row(Start_Index:end));
                        New_Env{end+1,1} = Env_row;
                    end
                end
                if Version_Check == "2022 R2"
                    for i = 1:length(New_Env)
                        New_Env_Line = New_Env{i};
                        if contains(New_Env_Line, 'v222')
                            ans_path = New_Env_Line;
                        end
                    end
                end
                if Version_Check =="2023 R1"
                    for i = 1:length(New_Env)
                        New_Env_Line = New_Env{i};
                        if contains(New_Env_Line, 'v231')
                            ans_path = New_Env_Line;
                        end
                    end
                end
                if Version_Check =="2023 R2"
                    for i = 1:length(New_Env)
                        New_Env_Line = New_Env{i};
                        if contains(New_Env_Line, 'v232')
                            ans_path = New_Env_Line;
                        end
                    end
                end
                if Version_Check =="2024 R1"
                    for i = 1:length(New_Env)
                        New_Env_Line = New_Env{i};
                        if contains(New_Env_Line, 'v242')
                            ans_path = New_Env_Line;
                        end
                    end
                end

                all_stages_batch = [tempdir, 'run_all_turbogrid.bat'];
                fid_all = fopen(all_stages_batch, 'w');
                fprintf(fid_all, '@echo off\n');
                fprintf(fid_all, 'echo Starting TurboGrid meshing processing\n');

                for a = app.Start_Stage:app.End_Stage
                    path_cfxtg = sprintf('%s\\TurboGrid\\bin\\cfxtg.exe', convertCharsToStrings(ans_path));
                    path_cfxtg = replace(path_cfxtg, "\", "/");
                    nz_tse_file_name = sprintf('nzl_%02d.tse', a);
                    bc_tse_file_name = sprintf('bck_%02d.tse', a);

                    fprintf(fid_all, 'echo Processing Nozzle Stage %d...\n', a);
                    fprintf(fid_all, '"%s" -batch %s%s\n', path_cfxtg, app.path, nz_tse_file_name);
                    fprintf(fid_all, 'if errorlevel 1 (\n');
                    fprintf(fid_all, '    echo Error processing Nozzle Stage %d\n', a);
                    fprintf(fid_all, '    pause\n');
                    fprintf(fid_all, '    exit /b 1\n');
                    fprintf(fid_all, ')\n');
                    fprintf(fid_all, 'echo Nozzle Stage %d meshing completed\n', a);

                    fprintf(fid_all, 'echo Processing Bucket Stage %d...\n', a);
                    fprintf(fid_all, '"%s" -batch %s%s\n', path_cfxtg, app.path, bc_tse_file_name);
                    fprintf(fid_all, 'if errorlevel 1 (\n');
                    fprintf(fid_all, '    echo Error processing Bucket Stage %d\n', a);
                    fprintf(fid_all, '    pause\n');
                    fprintf(fid_all, '    exit /b 1\n');
                    fprintf(fid_all, ')\n');
                    fprintf(fid_all, 'echo Bucket Stage %d meshing completed\n', a);

                    Work_count = Work_count + 1;
                end

                fprintf(fid_all, 'echo All TurboGrid meshing processing completed\n');
                fprintf(fid_all, 'echo Completed > "%s_all_completed.txt"\n', tempdir);
                fprintf(fid_all, 'exit\n');
                fclose(fid_all);

                cmd_all = sprintf('powershell -Command "Start-Process \"%s\" -Verb RunAs -Wait"', all_stages_batch);
                system(cmd_all);

                Data_File_Folder = [app.path, 'Data File'];
                Data_File_Folder = replace(Data_File_Folder, "\", "/");

                for a = 1:app.Stage_Number
                    files_to_move = {
                        sprintf('nzl%02d_hub.curve',a);
                        sprintf('bck%02d_hub.curve',a);
                        sprintf('nzl%02d_shroud.curve',a);
                        sprintf('bck%02d_shroud.curve',a);
                        sprintf('nzl_%02d.inf',a);
                        sprintf('bck_%02d.inf',a);
                        sprintf('nzl_%02d.tst',a);
                        sprintf('bck_%02d.tst',a);
                        sprintf('nzl_%02d.tse',a);
                        sprintf('bck_%02d.tse',a);
                        sprintf('nzl%02d_blade_offset.curve',a);
                        sprintf('bck%02d_blade_offset.curve',a);
                        sprintf('HP_nzl%02d_blade_offset.curve',a);
                        sprintf('HP_bck%02d_blade_offset.curve',a);
                        sprintf('IP_nzl%02d_blade_offset.curve',a);
                        sprintf('IP_bck%02d_blade_offset.curve',a);
                        sprintf('HP_nzl%02d_blade.curve',a);
                        sprintf('HP_bck%02d_blade.curve',a);
                        sprintf('IP_nzl%02d_blade.curve',a);
                        sprintf('IP_bck%02d_blade.curve',a)
                        sprintf('cfxtg_error.log')
                        };

                    for i = 1:length(files_to_move)
                        source_file = fullfile(app.path, files_to_move{i});
                        if isfile(source_file)
                            try
                                movefile(source_file, Data_File_Folder);
                            catch
                                continue
                            end
                        end
                    end
                end

                msgbox('저장 되었습니다.', '작업 완료', 'info');

            catch ME
                logFilePath = fullfile(pwd,'app_error_log.txt');
                fid = fopen(logFilePath, 'w');
                if fid ~= -1
                    fprintf(fid, '오류 발생 시간: %s\n', datestr(now));
                    fprintf(fid, '오류 메시지: %s\n\n', ME.message);
                    fprintf(fid, 'Stack Code :\n');
                    for k = 1:length(ME.stack)
                        fprintf(fid, 'File: %s\n', ME.stack(k).file);
                        fprintf(fid, 'Name: %s\n', ME.stack(k).name);
                        fprintf(fid, 'Line: %d\n\n', ME.stack(k).line);
                    end
                    fclose(fid);
                    errordlg(sprintf('오류 발생. 로그 파일을 확인하세요:\n%s', logFilePath), '오류 발생');
                end
            end
        end

