            Parameter_type11_Val = app.type11(:,2);
            Parameter_Type12_Val = app.type12(:,2);
            Parameter_Type13_Val = app.type13(:,2);
            Parameter_Type14_Val = app.type14(:,2);
            Parameter_Type15_Val = app.type15(:,2);

            app.com_val_New = {};

            matches_Name_1 = Parameter_Type1_Name(cellfun(@(x) contains(x, 'MAT'),Parameter_Type1_Name));
            matches_Val_1 = Parameter_Type1_Val(cellfun(@(x) contains(x, 'MAT'),Parameter_Type1_Name));
            app.matches_1 = [matches_Name_1, matches_Val_1];
            matches_Name_2 = Parameter_Type2_Name(cellfun(@(x) contains(x, 'MAT'),Parameter_Type2_Name));
            matches_Val_2 = Parameter_Type2_Val(cellfun(@(x) contains(x, 'MAT'),Parameter_Type2_Name));
            app.matches_2 = [matches_Name_2, matches_Val_2];
            matches_Name_3 = Parameter_Type3_Name(cellfun(@(x) contains(x, 'MAT'),Parameter_Type3_Name));
            matches_Val_3 = Parameter_Type3_Val(cellfun(@(x) contains(x, 'MAT'),Parameter_Type3_Name));
            app.matches_3 = [matches_Name_3, matches_Val_3];
            matches_Name_4 = Parameter_Type4_Name(cellfun(@(x) contains(x, 'MAT'),Parameter_Type4_Name));
            matches_Val_4 = Parameter_Type4_Val(cellfun(@(x) contains(x, 'MAT'),Parameter_Type4_Name));
            app.matches_4 = [matches_Name_4, matches_Val_4];
            matches_Name_5 = Parameter_Type5_Name(cellfun(@(x) contains(x, 'MAT'),Parameter_Type5_Name));
            matches_Val_5 = Parameter_Type5_Val(cellfun(@(x) contains(x, 'MAT'),Parameter_Type5_Name));
            app.matches_5 = [matches_Name_5, matches_Val_5];
            matches_Name_6 = Parameter_Type6_Name(cellfun(@(x) contains(x, 'MAT'),Parameter_Type6_Name));
            matches_Val_6 = Parameter_Type6_Val(cellfun(@(x) contains(x, 'MAT'),Parameter_Type6_Name));
            app.matches_6 = [matches_Name_6, matches_Val_6];
            matches_Name_7 = Parameter_Type7_Name(cellfun(@(x) contains(x, 'MAT'),Parameter_Type7_Name));
            matches_Val_7 = Parameter_Type7_Val(cellfun(@(x) contains(x, 'MAT'),Parameter_Type7_Name));
            app.matches_7 = [matches_Name_7, matches_Val_7];
            matches_Name_8 = Parameter_Type8_Name(cellfun(@(x) contains(x, 'MAT'),Parameter_Type8_Name));
