        % Button pushed function: Interstage_JournalButton
        function Interstage_JournalButtonPushed(app, event)

            WB_Path = replace(pwd, "\", "/");

            Work =  app.End_Stage - app.Start_Stage;
            Work_count = 0;

            status_bar = waitbar(0, 'Generating Journal File...', 'Name', 'Packing Seal Mesh File', 'CreateCancelBtn', 'setappdata(gcbf,''canceling'',1)');
            setappdata(status_bar, 'canceling', 0);

            for i = app.Start_Stage : app.End_Stage

                if getappdata(status_bar, 'canceling')
                    msgbox('작업이 취소되었습니다.', '작업 취소', 'warn');
                    delete(status_bar);
                    return;
                end

                waitbar(Work_count/Work, status_bar, sprintf('Generating Interstage Journal File...'));

                Journal_File = fopen('WB_Journal.txt','w');
                fprintf(Journal_File,newline);
                fprintf(Journal_File,newline);
                fprintf(Journal_File,'####################### Workbench File Open #######################\n');
                fprintf(Journal_File,'Open(FilePath="%s/Doosan_Interstage_Seal_251105.wbpj")\n', WB_Path);
                fprintf(Journal_File,'\n');
                DropDown_tag_name = sprintf('DropDown_Tag_%d', i) ;
                Table_tag_name = sprintf('Table_Tag_%d', i) ;
                data_dropdown = findobj(app.Interstage_Seal_Parameter_Table_Panel,'Tag', DropDown_tag_name);
                data_table = findobj(app.Interstage_Seal_Parameter_Table_Panel,'Tag', Table_tag_name);

                if ~isempty(data_dropdown)
                    Table_Data_GUI = [data_table.ColumnName, data_table.Data'];
                    Seal_L = app.matches_data(cellfun(@(x) contains(x, 'MAT_L'),app.matches_data));
                    Turbine_Part = app.matches_data(cellfun(@(x) contains(x, 'MAT_Flip_Seal'),app.matches_data));
                    Seal_Position = app.matches_data(cellfun(@(x) contains(x, 'MAT_Position'),app.matches_data));
                    Seal_L_Value = app.Stage_NzlRW(i,:);

                    if app.Minus_CheckBox.Value
                        Turbine_Part_Value = '180';
                    elseif app.Plus_CheckBox.Value
                        Turbine_Part_Value = '0';
                    end

                    Seal_Position_Value = app.hub_nz_in_x(i,:);
                    app.matches_data=[Seal_L, arrayfun(@(x){x},Seal_L_Value); Turbine_Part, cellstr(Turbine_Part_Value); Seal_Position, arrayfun(@(x){x},Seal_Position_Value)];
                    app.matches_data{1,2}=num2str(app.matches_data{1,2});
                    app.matches_data{3,2}=num2str(app.matches_data{3,2});

                    Seal_Data_Value = {} ;
                    Seal_Data_Parameter = [data_table.ColumnName; app.matches_data(:,1)];
                    Seal_Data_Value = [transpose(data_table.Data); app.matches_data(:,2)];
                    Seal_Type_Colum = {} ;
                    Seal_Type_Name = lower(strrep(data_dropdown.Value,' ',''));

                    for j = 1 : height(Seal_Data_Parameter)
                        Seal_Type_Colum{j} = sprintf('%s_',Seal_Type_Name) ;
                    end
                    Seal_Type_Colum = transpose(Seal_Type_Colum);
                    Seal_Data = strcat(Seal_Type_Colum,Seal_Data_Parameter);
                    Seal_Data_New = {};
                    trim_Data_New = {};
                    for k = 1 : height(Seal_Data)
                        Seal_Data_New = Seal_Data{k};
                        for h = 1 : height(app.prameter_name)
                            prameter_name_New = app.prameter_name{h};
                            if contains(prameter_name_New, cellstr(Seal_Data_New))
                                Seal_Data_Index = strfind(prameter_name_New,'-');
                                Seal_Data_Cut = Seal_Data_Index - 2;
                                prameter_name_New = strtrim(prameter_name_New(1:Seal_Data_Cut));
                                trim_Data_New(end+1,1) = cellstr(prameter_name_New);
                            end
                        end
                    end
                end

                if app.HP_CheckBox.Value
                    Journal_Number = sprintf('HP_IS_%02d', i);
                    Extend_I_Number = sprintf('HP_IS_IN_%02d', i);
                    Extend_O_Number = sprintf('HP_IS_OUT_%02d', i);
                else
                    Journal_Number = sprintf('IP_IS_%02d', i);
                    Extend_I_Number = sprintf('IP_IS_IN_%02d', i);
                    Extend_O_Number = sprintf('IP_IS_OUT_%02d', i);
                end

                Journal_Data = [Seal_Data, trim_Data_New, Seal_Data_Value];
                Journal_Data = cell2table(Journal_Data);
                eval([Journal_Number ' = Journal_Data;']);

                CR_1 = Journal_Data(contains(Journal_Data.Journal_Data1,'_CR1'), :);
                CR_1 = CR_1{1,3};
                CR_1 = str2double(CR_1);

                B_1 = Journal_Data(contains(Journal_Data.Journal_Data1,'_B1'), :);
                B_1 = B_1{1,3};
                B_1 = str2double(B_1);

                fprintf(Journal_File,newline);
                fprintf(Journal_File,'####################### %s Update Code #######################\n',Journal_Number);
                fprintf(Journal_File,newline);

                for l = 1 : height(Journal_Data)
                    Parameter_Name_Read = cell2mat(Journal_Data{l,2});
                    Parameter_Val_Read = cell2mat(Journal_Data{l,3});
                    if any(str2double(Parameter_Val_Read) == [0, 180])
                        fprintf(Journal_File,'Parameters.GetParameter(Name="%s").Expression = str( %s )+"[degree]"\n', Parameter_Name_Read , Parameter_Val_Read);
                    else
                        fprintf(Journal_File,'Parameters.GetParameter(Name="%s").Expression = str( %s )+"[mm]"\n', Parameter_Name_Read , Parameter_Val_Read);
                    end
                end

                fprintf(Journal_File,newline);
                fprintf(Journal_File,'system1 = GetSystem(Name="%s")\n',app.com_val_New{i,1});
                fprintf(Journal_File,'geometryComponent1 = system1.GetComponent(Name="Geometry")\n');
                fprintf(Journal_File,'geometryComponent1.Update(AllDependencies=True)\n');
                fprintf(Journal_File,'meshComponent1 = system1.GetComponent(Name="Mesh")\n');
                fprintf(Journal_File,'meshComponent1.Update(AllDependencies=True)\n');
                fprintf(Journal_File,newline);
                fprintf(Journal_File,'mshPath=r"%s%s.msh" \n', app.path, Journal_Number);
                fprintf(Journal_File,'mshPath = mshPath.replace(''\\\\'', ''\\\\\\\\'')\n');
                fprintf(Journal_File,'system = GetSystem(Name="%s")\n', app.com_val_New{i,1});
                fprintf(Journal_File,'mesh = system.GetContainer(ComponentName="Mesh")\n');
                fprintf(Journal_File,'mesh.Edit()\n');
                fprintf(Journal_File,'command2Send = """DS = WB.AppletList.Applet("DSApplet").App;\n');
                fprintf(Journal_File,'var meshBranch = DS.Tree.FirstActiveBranch.MeshControlGroup;\n');
                fprintf(Journal_File,'var filename = "%%s";\n');
                fprintf(Journal_File,'DS.Script.doFileExport(filename);""" %%(mshPath)\n');
                fprintf(Journal_File,'mesh.SendCommand(Command = command2Send)\n');
                fprintf(Journal_File,'mesh.Exit()\n');
                fprintf(Journal_File,newline);
                fprintf(Journal_File,'####################### %s End #######################\n',Journal_Number);

                if i~=app.Start_Stage
                    ExtendI_R = {};
                    ExtendI_GW1 = {};
                    for n = 1: length(Table_Data_GUI)
                        if contains(Table_Data_GUI{n,1}, 'R [mm]')
                            ExtendI_R = Table_Data_GUI{n,2};
                        end
                        if contains(Table_Data_GUI{n,1}, 'GB1 [mm]')
                            ExtendI_GB1 = Table_Data_GUI{n,2};
                        end
                    end

                    if Seal_Type_Name == "type13"
                        ExtendI_R = str2double(ExtendI_R) - str2double(ExtendI_GB1);
                    end
                    ExtendI_L_length = app.hub_bc_out_x(i-1,:) - app.hub_nz_in_x(i,:);
                    ExtendI_L = abs(ExtendI_L_length);
                    ExtendI_nz_in_y = app.hub_nz_in_z(i,:);
                    ExtendI_bc_out_y = app.hub_bc_out_z(i-1,:);
                    ExtendI_Position = app.hub_nz_in_x(i,:);
                    ExtendI_Imprint =  CR_1(1,:) + B_1(1,:);
                    ExtendI_Flip = {};
                    if app.Minus_CheckBox.Value
                        ExtendI_Flip = '180';
                    else
                        ExtendI_Flip = '0';
                    end
                    fprintf(Journal_File,newline);
                    fprintf(Journal_File,newline);
                    fprintf(Journal_File,'####################### %s Update Code #######################\n',Extend_I_Number);
                    fprintf(Journal_File,newline);
                    fprintf(Journal_File,'Parameters.GetParameter(Name="P626").Expression = str( %s )+"[mm]"\n', convertCharsToStrings(ExtendI_R));
                    fprintf(Journal_File,'Parameters.GetParameter(Name="P627").Expression = str( %s )+"[mm]"\n', num2str(ExtendI_L));
                    fprintf(Journal_File,'Parameters.GetParameter(Name="P638").Expression = str( %s )+"[mm]"\n', num2str(ExtendI_nz_in_y));
                    fprintf(Journal_File,'Parameters.GetParameter(Name="P639").Expression = str( %s )+"[mm]"\n', num2str(ExtendI_bc_out_y));
                    fprintf(Journal_File,'Parameters.GetParameter(Name="P630").Expression = str( %s )+"[mm]"\n', num2str(ExtendI_Position));
                    fprintf(Journal_File,'Parameters.GetParameter(Name="P631").Expression = str( %s )+"[degree]"\n', ExtendI_Flip);
                    fprintf(Journal_File,'Parameters.GetParameter(Name="P656").Expression = str( %s )+"[mm]"\n', ExtendI_Imprint);
                    fprintf(Journal_File,newline);
                    fprintf(Journal_File,'system1 = GetSystem(Name="SYS 3")\n');
                    fprintf(Journal_File,'geometryComponent1 = system1.GetComponent(Name="Geometry")\n');
                    fprintf(Journal_File,'geometryComponent1.Update(AllDependencies=True)\n');
                    fprintf(Journal_File,'meshComponent1 = system1.GetComponent(Name="Mesh")\n');
                    fprintf(Journal_File,'meshComponent1.Update(AllDependencies=True)\n');
                    fprintf(Journal_File,newline);
                    fprintf(Journal_File,'mshPath=r"%s%s.msh" \n', app.path, Extend_I_Number);
                    fprintf(Journal_File,'mshPath = mshPath.replace(''\\\\'', ''\\\\\\\\'')\n');
                    fprintf(Journal_File,'system = GetSystem(Name="SYS 3")\n');
                    fprintf(Journal_File,'mesh = system.GetContainer(ComponentName="Mesh")\n');
                    fprintf(Journal_File,'mesh.Edit()\n');
                    fprintf(Journal_File,'command2Send = """DS = WB.AppletList.Applet("DSApplet").App;\n');
                    fprintf(Journal_File,'var meshBranch = DS.Tree.FirstActiveBranch.MeshControlGroup;\n');
                    fprintf(Journal_File,'var filename = "%%s";\n');
                    fprintf(Journal_File,'DS.Script.doFileExport(filename);""" %%(mshPath)\n');
                    fprintf(Journal_File,'mesh.SendCommand(Command = command2Send)\n');
                    fprintf(Journal_File,'mesh.Exit()\n');
                    fprintf(Journal_File,newline);
                    fprintf(Journal_File,'####################### %s End #######################\n',Extend_I_Number);
                else
                    ExtendI_R = {};
                    for n = 1: length(Table_Data_GUI)
                        if contains(Table_Data_GUI{n,1}, 'R [mm]')
                            ExtendI_R = Table_Data_GUI{n,2};
                        end
                    end
                    ExtendI_L_length = 10;
                    ExtendI_L = abs(ExtendI_L_length);
                    match_R = cellfun(@(x) strcmp(x, 'R [mm]'), Table_Data_GUI(:,1));
                    Extend_R = Table_Data_GUI(match_R, 2);
