        % Button pushed function: Interstage_MeshButton
        function Interstage_MeshButtonPushed(app, event)
            app.path = replace(app.path, "\", "/");
            ans_path = {} ;
            Version_Check = app.CFX_Version_DropDown.Value;
            [Zero, Env] = system('set');
            Env = splitlines(Env);
            New_Env = {};
            Work =  app.End_Stage - app.Start_Stage;
            Work_count = 0;
            for i = 1:length(Env)
                Env_row = Env{i};
                if contains(Env_row, 'AWP_ROOT', 'IgnoreCase', true)
                    Env_Index = strfind(Env_row, '=');
                    Start_Index = Env_Index + 1;
                    Env_row = strtrim(Env_row(Start_Index:end));
                    New_Env{end+1,1} = Env_row;
                end
            end
            if Version_Check == "2022 R2"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v222')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2023 R1"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v231')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2023 R2"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v232')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2024 R1"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v242')
                        ans_path = New_Env_Line;
                    end
                end
            end
            status_bar = waitbar(0, 'Generating Mesh File...', 'Name', 'Packing Seal Mesh File', 'CreateCancelBtn', 'setappdata(gcbf,''canceling'',1)');
            setappdata(status_bar, 'canceling', 0);
            for i = app.Start_Stage:app.End_Stage
                waitbar(Work_count/Work, status_bar, sprintf('Generating Mesh for Interstage Seal %d...', i));
                Interstage_Journal_File_Name_WB = sprintf('Interstage_Seal_Stage%d.wbjn', i);
                Path_WB = """" + convertCharsToStrings(ans_path) + """" + "\Framework\bin\Win64\runwb2.exe" ;
                dos(Path_WB + " -B -R " + convertCharsToStrings(app.path) +Interstage_Journal_File_Name_WB)
                if getappdata(status_bar, 'canceling')
                    msgbox('작업이 취소되었습니다.', '작업 취소', 'warn');
                    delete(status_bar);
                    return;
                end
                Work_count = Work_count+1;
            end
            delete(status_bar);
            msgbox('저장 되었습니다.');

            Data_File_Folder = [app.path, 'Data File'];
            Data_File_Folder = replace(Data_File_Folder, "\", "/");

            for a = app.Start_Stage:app.End_Stage
                movefile(fullfile(app.path,sprintf('Interstage_Seal_Stage%d.wbjn',a)), Data_File_Folder);
            end
        end

        % Callback function
        function Blade_Offset_ButtonPushed(app, event)
            app.path = replace(app.path, "\", "/");
            defaultValue = {'Offset Value'};
            answer = inputdlg('Blade Offset Value: [mm]', 'Blade Offset', [1 50], defaultValue);
            if isempty(answer)
                return;
            end
            num = str2double(answer{1});
            if isnan(num)
                errordlg('Blade Offset Value가 잘못 입력되었습니다.', 'Error');
                return;
            end
            offset_value = num;
            fig = figure('Name', sprintf('Blade Offset Result (Offset: %.2f mm)', offset_value), 'Position', [100, 100, 1200, 800], 'MenuBar', 'none', 'ToolBar', 'none');
            tabgroup = uitabgroup(fig, 'Position', [0 0 1 1]);
            set(fig, 'WindowScrollWheelFcn', @(src, event) app.wheel_zoom_helper(src, event));
            status_bar = waitbar(0, 'Blade Offset 진행 중...', 'Name', 'Blade Offset Progress');
            setappdata(status_bar, 'canceling', 0);
            cancel_btn = uicontrol('Parent', status_bar, 'Style', 'pushbutton', 'String', 'Cancel', 'Position', [280 3 60 20], 'Callback', @(src,event) setappdata(status_bar, 'canceling', 1));
            try
                for h = 1:app.Stage_Number
                    if getappdata(status_bar, 'canceling')
                        delete(status_bar);
                        delete(fig);
                        msgbox('작업이 취소되었습니다.', '작업 취소', 'warn');
                        return;
                    end
                    waitbar(h/app.Stage_Number, status_bar, sprintf('Stage %d/%d 처리 중...', h, app.Stage_Number));
                    tab = uitab(tabgroup, 'Title', sprintf('Stage %d', h));
                    nzl_filename = sprintf('nzl%02d_blade.curve', h);
                    [nzl_blade_points, nzl_offset_points] = app.process_blade_file_helper(nzl_filename, offset_value, app.path);
                    bck_filename = sprintf('bck%02d_blade.curve', h);
                    [bck_blade_points, bck_offset_points] = app.process_blade_file_helper(bck_filename, offset_value, app.path);

                    if app.Minus_CheckBox.Value == true
                        nzl_blade_points{1}(:,1) = -abs(nzl_blade_points{1}(:,1));
                    elseif app.Plus_CheckBox.Value == true
                        nzl_blade_points{1}(:,1) = abs(nzl_blade_points{1}(:,1));
                    end

                    ax1 = axes('Position', [0.01 0.05 0.49 0.9], 'Parent', tab);
                    plot(ax1, [nzl_blade_points{1}(:,1); nzl_blade_points{1}(1,1)], ...
                        [nzl_blade_points{1}(:,2); nzl_blade_points{1}(1,2)], 'k-', 'LineWidth', 1);
                    hold(ax1, 'on');
                    plot(ax1, [nzl_offset_points{1}(:,1); nzl_offset_points{1}(1,1)], ...
                        [nzl_offset_points{1}(:,2); nzl_offset_points{1}(1,2)], 'r-', 'LineWidth', 1);
                    title(ax1, sprintf('Stage %d - Nozzle Blade Offset', h), 'FontSize', 10);
                    axis(ax1, 'equal');
                    ax1.XAxis.TickLabels = {};
                    ax1.YAxis.TickLabels = {};
                    ax1.XAxis.TickLength = [0 0];
                    ax1.YAxis.TickLength = [0 0];
                    legend(ax1, 'Original Blade', 'Offset Blade', 'Location', 'southoutside', 'Orientation', 'horizontal');
                    hold(ax1, 'off');

                    if app.Minus_CheckBox.Value == true
                        bck_blade_points{1}(:,1) = -abs(bck_blade_points{1}(:,1));
                    elseif app.Plus_CheckBox.Value == true
                        bck_blade_points{1}(:,1) = abs(bck_blade_points{1}(:,1));
                    end

                    ax2 = axes('Position', [0.501 0.05 0.49 0.9], 'Parent', tab);
                    plot(ax2, [bck_blade_points{1}(:,1); bck_blade_points{1}(1,1)], ...
                        [bck_blade_points{1}(:,2); bck_blade_points{1}(1,2)], 'k-', 'LineWidth', 1);
                    hold(ax2, 'on');
                    plot(ax2, [bck_offset_points{1}(:,1); bck_offset_points{1}(1,1)], ...
                        [bck_offset_points{1}(:,2); bck_offset_points{1}(1,2)], 'r-', 'LineWidth', 1);
                    title(ax2, sprintf('Stage %d - Bucket Blade Offset', h), 'FontSize', 10);
                    axis(ax2, 'equal');
                    ax2.XAxis.TickLabels = {};
                    ax2.YAxis.TickLabels = {};
                    ax2.XAxis.TickLength = [0 0];
                    ax2.YAxis.TickLength = [0 0];
                    legend(ax2, 'Original Blade', 'Offset Blade', 'Location', 'southoutside', 'Orientation', 'horizontal');
                    hold(ax2, 'off');
                    zoom(ax1, 'on');
                    pan(ax1, 'on');
                    zoom(ax2, 'on');
                    pan(ax2, 'on');
                end
                delete(status_bar);
                msgbox('저장 되었습니다.', '작업 완료', 'info');
            catch ME
                delete(status_bar);
                delete(fig);
                errordlg(['오류 발생: ' ME.message], '오류');
            end
        end

        % Callback function
        function BladeOffsetCheckBoxValueChanged(app, event)
            if app.BladeOffsetCheckBox.Value
                app.Blade_Offset_Button.Enable = 'On';
            else
                app.Blade_Offset_Button.Enable = 'off';
            end
        end

        % Value changed function: Tip_Seal_Type_ListBox
        function Tip_Seal_Type_ListBoxValueChanged(app, event)
            pathToMLAPP = fileparts(mfilename('fullpath'));
            pathToMLAPP = replace(pathToMLAPP, "\", "/");
            Seal_Type_value = app.Tip_Seal_Type_ListBox.Value;
            if Seal_Type_value == "Type 1"
                app.Tip_Seal_Image.ImageSource = fullfile(pathToMLAPP, 'pic', 'tip_type1.jpg');
            end
            if Seal_Type_value == "Type 2"
                app.Tip_Seal_Image.ImageSource = fullfile(pathToMLAPP, 'pic', 'tip_type2.jpg');
            end
            if Seal_Type_value == "Type 3"
                app.Tip_Seal_Image.ImageSource = fullfile(pathToMLAPP, 'pic', 'tip_type3.jpg');
            end
            if Seal_Type_value == "Type 4"
                app.Tip_Seal_Image.ImageSource = fullfile(pathToMLAPP, 'pic', 'tip_type4.jpg');
            end
            if Seal_Type_value == "Type 5"
                app.Tip_Seal_Image.ImageSource = fullfile(pathToMLAPP, 'pic', 'tip_type5.jpg');
            end
            if Seal_Type_value == "Type 6"
                app.Tip_Seal_Image.ImageSource = fullfile(pathToMLAPP, 'pic', 'tip_type6.jpg');
            end
        end

        % Button pushed function: Tip_DataButton
        function Tip_DataButtonPushed(app, event)
            app.tip_type1 = sortrows(app.tip_type1,1);
            app.tip_type2 = sortrows(app.tip_type2,1);
            app.tip_type3 = sortrows(app.tip_type3,1);
            app.tip_type4 = sortrows(app.tip_type4,1);
            app.tip_type5 = sortrows(app.tip_type5,1);
            app.tip_type6 = sortrows(app.tip_type6,1);

            tip_Parameter_Type1_Name = app.tip_type1(:,1);
            tip_Parameter_Type2_Name = app.tip_type2(:,1);
            tip_Parameter_Type3_Name = app.tip_type3(:,1);
            tip_Parameter_Type4_Name = app.tip_type4(:,1);
            tip_Parameter_Type5_Name = app.tip_type5(:,1);
            tip_Parameter_Type6_Name = app.tip_type6(:,1);

