            tip_matches_Val_3 = tip_Parameter_Type3_Val(cellfun(@(x) contains(x, 'MAT'),tip_Parameter_Type3_Name));
            tip_matches_3 = [tip_matches_Name_3, tip_matches_Val_3];

            tip_type_Name_3 = tip_Parameter_Type3_Name(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type3_Name));
            tip_type_Val_3 = tip_Parameter_Type3_Val(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type3_Name));
            if app.IP_CheckBox.Value
                tip_type_ip_3 = contains(tip_type_Name_3(:,1), 'IL');
                tip_type_Val_3(tip_type_ip_3,1) = {'17'};
            end
