            tip_type3_trans = transpose(tip_type_3);
            tip_type3_row_name = tip_type3_trans(1,:);
            tip_type3_data_value = tip_type3_trans(2,:);

            tip_matches_Name_4 = tip_Parameter_Type4_Name(cellfun(@(x) contains(x, 'MAT'),tip_Parameter_Type4_Name));
            tip_matches_Val_4 = tip_Parameter_Type4_Val(cellfun(@(x) contains(x, 'MAT'),tip_Parameter_Type4_Name));
            tip_matches_4 = [tip_matches_Name_4, tip_matches_Val_4];

            tip_type_Name_4 = tip_Parameter_Type4_Name(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type4_Name));
            tip_type_Val_4 = tip_Parameter_Type4_Val(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type4_Name));
            if app.IP_CheckBox.Value
                tip_type_ip_4 = contains(tip_type_Name_4(:,1), 'IL');
                tip_type_Val_4(tip_type_ip_4,1) = {'17'};
            end
            tip_type_4 = [tip_type_Name_4, tip_type_Val_4];

            tip_type4_trans = transpose(tip_type_4);
            tip_type4_row_name = tip_type4_trans(1,:);
            tip_type4_data_value = tip_type4_trans(2,:);

            tip_matches_Name_5 = tip_Parameter_Type5_Name(cellfun(@(x) contains(x, 'MAT'),tip_Parameter_Type5_Name));
            tip_matches_Val_5 = tip_Parameter_Type5_Val(cellfun(@(x) contains(x, 'MAT'),tip_Parameter_Type5_Name));
            tip_matches_5 = [tip_matches_Name_5, tip_matches_Val_5];

            tip_type_Name_5 = tip_Parameter_Type5_Name(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type5_Name));
            tip_type_Val_5 = tip_Parameter_Type5_Val(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type5_Name));
            if app.IP_CheckBox.Value
                tip_type_ip_5 = contains(tip_type_Name_5(:,1), 'IL');
                tip_type_Val_5(tip_type_ip_5,1) = {'17'};
            end
            tip_type_5 = [tip_type_Name_5, tip_type_Val_5];

            tip_type5_trans = transpose(tip_type_5);
            tip_type5_row_name = tip_type5_trans(1,:);
            tip_type5_data_value = tip_type5_trans(2,:);

            tip_matches_Name_6 = tip_Parameter_Type6_Name(cellfun(@(x) contains(x, 'MAT'),tip_Parameter_Type6_Name));
            tip_matches_Val_6 = tip_Parameter_Type6_Val(cellfun(@(x) contains(x, 'MAT'),tip_Parameter_Type6_Name));
            tip_matches_6 = [tip_matches_Name_6, tip_matches_Val_6];

            tip_type_Name_6 = tip_Parameter_Type6_Name(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type6_Name));
            tip_type_Val_6 = tip_Parameter_Type6_Val(cellfun(@(x) ~contains(x, 'MAT'),tip_Parameter_Type6_Name));
            if app.IP_CheckBox.Value
                tip_type_ip_6 = contains(tip_type_Name_6(:,1), 'IL');
                tip_type_Val_6(tip_type_ip_6,1) = {'17'};
            end
            tip_type_6 = [tip_type_Name_6, tip_type_Val_6];

            tip_type6_trans = transpose(tip_type_6);
            tip_type6_row_name = tip_type6_trans(1,:);
            tip_type6_data_value = tip_type6_trans(2,:);

            for i = 1 : app.Stage_Number

                DropDown_tag_name = sprintf('Tip_DropDown_Tag_%d', i) ;
                Table_tag_name = sprintf('Tip_Table_Tag_%d', i) ;
                data_dropdown = findobj(app.Tip_Seal_Parameter_Table_Panel,'Tag', DropDown_tag_name);
                data_table = findobj(app.Tip_Seal_Parameter_Table_Panel,'Tag', Table_tag_name);
                if ~isempty(data_dropdown)
                    data_dropdown_val = data_dropdown.Value;
                    if data_dropdown_val == "Type 1"
                        data_table.ColumnName = tip_type1_row_name;
                        data_table.Data = tip_type1_data_value;
                        app.matches_data = tip_matches_1;
                        com_val = "SYS 1";
                    end
                end
                if ~isempty(data_dropdown)
                    data_dropdown_val = data_dropdown.Value;
                    if data_dropdown_val == "Type 2"
                        data_table.ColumnName = tip_type2_row_name;
                        data_table.Data = tip_type2_data_value;
                        app.matches_data = tip_matches_2;
                        com_val = "SYS 3";
                    end
                end
                if ~isempty(data_dropdown)
                    data_dropdown_val = data_dropdown.Value;
                    if data_dropdown_val == "Type 3"
                        data_table.ColumnName = tip_type3_row_name;
                        data_table.Data = tip_type3_data_value;
                        app.matches_data = tip_matches_3;
                        com_val = "SYS 4";
                    end
                end
                if ~isempty(data_dropdown)
                    data_dropdown_val = data_dropdown.Value;
                    if data_dropdown_val == "Type 4"
                        data_table.ColumnName = tip_type4_row_name;
                        data_table.Data = tip_type4_data_value;
                        app.matches_data = tip_matches_4;
                        com_val = "SYS 5";
                    end
                end
                if ~isempty(data_dropdown)
                    data_dropdown_val = data_dropdown.Value;
                    if data_dropdown_val == "Type 5"
                        data_table.ColumnName = tip_type5_row_name;
                        data_table.Data = tip_type5_data_value;
                        app.matches_data = tip_matches_5;
                        com_val = "SYS 6";
                    end
                end
                if ~isempty(data_dropdown)
                    data_dropdown_val = data_dropdown.Value;
                    if data_dropdown_val == "Type 6"
                        data_table.ColumnName = tip_type6_row_name;
                        data_table.Data = tip_type6_data_value;
                        app.matches_data = tip_matches_6;
                        com_val = "SYS 8";
                    end
                end
                app.com_tip_val_New{end+1,1} = com_val;
            end

            app.Tip_JournalButton.Enable = 'On';

        end

        % Button pushed function: Tip_JournalButton
        function Tip_JournalButtonPushed(app, event)
            WB_Path = replace(pwd, "\", "/");
            CR_R_Tabel = table();
            app.SB_Number = 0;
            app.SB_Position = zeros(app.Stage_Number,1);
            app.Brush_Number = 0;
            app.Brush_Position = zeros(app.Stage_Number,1);
            status_bar = waitbar(0, 'Generating Journal File...', 'Name', 'Packing Seal Mesh File', 'CreateCancelBtn', 'setappdata(gcbf,''canceling'',1)');
            setappdata(status_bar, 'canceling', 0);

            Work =  app.End_Stage - app.Start_Stage;
            Work_count = 0;
            for i = app.Start_Stage:app.End_Stage

                if getappdata(status_bar, 'canceling')
                    msgbox('작업이 취소되었습니다.', '작업 취소', 'warn');
                    delete(status_bar);
                    return;
                end

                waitbar(Work_count/Work, status_bar, sprintf('Generating Tip Seal Journal File...'));
                Journal_File = fopen('WB_Journal.txt','w');
                fprintf(Journal_File,newline);
                fprintf(Journal_File,newline);
                fprintf(Journal_File,'####################### Workbench File Open #######################\n');
                fprintf(Journal_File,'Open(FilePath="%s/Doosan_Tip_Seal_brush_251105.wbpj")\n', WB_Path);
                fprintf(Journal_File,'\n');
                Tip_DropDown_tag_name = sprintf('Tip_DropDown_Tag_%d', i) ;
                Tip_Table_tag_name = sprintf('Tip_Table_Tag_%d', i) ;
                %Honeycomb_Size_tag_name = sprintf('Tip_Seal_DropDown_Tag_%d', i) ;
                Extraction_Checkbox = sprintf('Tip_Seal_Checkbox_%d', i) ;
                Extraction_Value = sprintf('Tip_Seal_text_%d', i) ;
                Tip_data_dropdown = findobj(app.Tip_Seal_Parameter_Table_Panel,'Tag', Tip_DropDown_tag_name);
                Tip_data_table = findobj(app.Tip_Seal_Parameter_Table_Panel,'Tag', Tip_Table_tag_name);
                %Honeycomb_Size = findobj(app.Tip_Seal_Parameter_Table_Panel,'Tag', Honeycomb_Size_tag_name);
                Extraction_Checkbox_data = findobj(app.Tip_Seal_Parameter_Table_Panel,'Tag', Extraction_Checkbox);
                Extraction_Value_data = findobj(app.Tip_Seal_Parameter_Table_Panel,'Tag', Extraction_Value);

                if ~isempty(Tip_data_dropdown)
                    Table_Data_GUI = [Tip_data_table.ColumnName, Tip_data_table.Data'];

                    %{
                    if Honeycomb_Size.Value == "7.3mm"
                        Honeycomb_Size = 7.3;
                    else
                        Honeycomb_Size = 9.7;
                    end
                    %}

                    if app.HP_CheckBox.Value
                        Journal_Number = sprintf('HP_Tip_%02d', i);
                        Journal_I_Number = sprintf('HP_NB_%02d', i);
                        Journal_O_Number = sprintf('HP_BN_%02d', i);
                    else
                        Journal_Number = sprintf('IP_Tip_%02d', i);
                        Journal_I_Number = sprintf('IP_NB_%02d', i);
                        Journal_O_Number = sprintf('IP_BN_%02d', i);
                    end

                    if Tip_data_dropdown.Value == "Type 1"

                        match_B1 = cellfun(@(x) strcmp(x, 'B1 [mm]'), Table_Data_GUI(:,1));
                        type1t_B1 = Table_Data_GUI(match_B1, 2);
                        match_CR1 = cellfun(@(x) strcmp(x, 'CR1 [mm]'), Table_Data_GUI(:,1));
                        type1t_CR1 = Table_Data_GUI(match_CR1, 2);
                        match_S1 = cellfun(@(x) strcmp(x, 'S1 [mm]'), Table_Data_GUI(:,1));
                        type1t_S1 = Table_Data_GUI(match_S1, 2);
                        match_EL1 = cellfun(@(x) strcmp(x, 'EL1 [mm]'), Table_Data_GUI(:,1));
                        type1t_EL1 = Table_Data_GUI(match_EL1, 2);
                        match_G1 = cellfun(@(x) strcmp(x, 'G1 [mm]'), Table_Data_GUI(:,1));
                        type1t_G1 = Table_Data_GUI(match_G1, 2);
                        match_GB1 = cellfun(@(x) strcmp(x, 'GB1 [mm]'), Table_Data_GUI(:,1));
                        type1t_GB1 = Table_Data_GUI(match_GB1, 2);
                        match_R = cellfun(@(x) strcmp(x, 'R [mm]'), Table_Data_GUI(:,1));
                        type1t_R = Table_Data_GUI(match_R, 2);
                        match_GW1 = cellfun(@(x) strcmp(x, 'GW1 [mm]'), Table_Data_GUI(:,1));
                        type1t_GW1 = Table_Data_GUI(match_GW1, 2);
                        match_GW2 = cellfun(@(x) strcmp(x, 'GW2 [mm]'), Table_Data_GUI(:,1));
                        type1t_GW2 = Table_Data_GUI(match_GW2, 2);
                        match_GB2 = cellfun(@(x) strcmp(x, 'GB2 [mm]'), Table_Data_GUI(:,1));
                        type1t_GB2 = Table_Data_GUI(match_GB2, 2);
                        match_EL2 = cellfun(@(x) strcmp(x, 'EL2 [mm]'), Table_Data_GUI(:,1));
                        type1t_EL2 = Table_Data_GUI(match_EL2, 2);
                        type1t_MAT1y = app.shroud_nz_out_z(i,:);
                        type1t_MAT2y = app.shroud_bc_in_z(i,:);
                        type1t_MAT3y = app.shroud_bc_out_z(i,:);

                        if i == app.Stage_Number
                            type1t_MAT4y = app.shroud_bc_out_z(i,:);
                        else
                            %type1t_MAT4y = app.shroud_nz_in_z_r(i+1,:);
                            type1t_MAT4y = app.shroud_nz_in_z_r(i+1,:) + app.r_Data;
                        end

                        hon_number = ((str2double(type1t_B1) + str2double(type1t_CR1) + str2double(type1t_R) )* 2 * pi) / ( (0.05 + 1.58) * 2);
                        hon_number = 2 * round(hon_number/2);
                        type1t_MATPitch = 360 / hon_number;
                        app.Pitch_Table(i,:) = type1t_MATPitch;
                        type1t_MATLocation = abs(app.shroud_nz_out_x(i,:));
                        type1t_MATIn = abs(app.shroud_nz_out_x(i,:) - app.shroud_bc_in_x(i,:));

                        if i == app.Stage_Number
                            type1t_MATOut = 10;
                        else
                            type1t_MATOut = abs(app.shroud_bc_out_x(i,:)-app.shroud_nz_in_x_r(i+1,:)) - app.r_Data;
                        end

                        if Extraction_Checkbox_data.Value
                            ext_L = Extraction_Value_data.Value;
                            type1t_MATOut = type1t_MATOut - ext_L;
                        end
                        type1t_GW2 = cell2mat(type1t_GW2);
                        type1t_GW2 = str2double(type1t_GW2) - 0.1;

                        if type1t_GW2 < 8
                            type1t_MATgap = 0.245;
                        else
                            type1t_MATgap = 0.183636363636363;
                        end

                        type1t_MATLen = app.Stage_BckShW(i,:);

                        fprintf(Journal_File,newline);
                        fprintf(Journal_File,'####################### %s Update Code #######################\n',Journal_Number);
                        fprintf(Journal_File,newline);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P1").Expression = str( %d )+"[mm]"\n', str2double(type1t_B1));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P2").Expression = str( %d )+"[mm]"\n', str2double(type1t_CR1));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P3").Expression = str( %d )+"[mm]"\n', str2double(type1t_S1));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P4").Expression = str( %d )+"[mm]"\n', str2double(type1t_EL1));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P5").Expression = str( %d )+"[mm]"\n', str2double(type1t_G1));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P8").Expression = str( %d )+"[mm]"\n', str2double(type1t_GB1));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P9").Expression = str( %d )+"[mm]"\n', str2double(type1t_R));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P10").Expression = str( %d )+"[mm]"\n', type1t_MAT1y);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P11").Expression = str( %d )+"[mm]"\n', type1t_MAT2y);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P12").Expression = str( %d )+"[mm]"\n', type1t_MAT3y);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P13").Expression = str( %d )+"[mm]"\n', type1t_MAT4y);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P20").Expression = str( %d )+"[mm]"\n', str2double(type1t_GW1));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P41").Expression = str( %d )+"[degree]"\n', type1t_MATPitch);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P43").Expression = str( %d )+"[mm]"\n', type1t_MATLocation);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P44").Expression = str( %d )+"[mm]"\n', str2double(type1t_GB2));
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P111").Expression = str( %d )+"[mm]"\n', type1t_MATIn);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P112").Expression = str( %d )+"[mm]"\n', type1t_MATOut);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P149").Expression = str( %d )+"[mm]"\n', type1t_GW2);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P151").Expression = str( %d )+"[mm]"\n', type1t_MATgap);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P165").Expression = str( %d )+"[mm]"\n', type1t_MATLen);
                        fprintf(Journal_File,'Parameters.GetParameter(Name="P271").Expression = str( %d )+"[mm]"\n', str2double(type1t_EL2));
                        fprintf(Journal_File,newline);
                        fprintf(Journal_File,'system1 = GetSystem(Name="SYS 1")\n');
                        fprintf(Journal_File,'geometryComponent1 = system1.GetComponent(Name="Geometry")\n');
                        fprintf(Journal_File,'geometryComponent1.Update(AllDependencies=True)\n');
                        fprintf(Journal_File,'meshComponent1 = system1.GetComponent(Name="Mesh")\n');
                        fprintf(Journal_File,'model1 = system1.GetContainer(ComponentName="Mesh")\n');
                        fprintf(Journal_File,'model1.Edit()\n');
                        fprintf(Journal_File,'model1.SendCommand(Language="Python",Command=\n');
                        fprintf(Journal_File,'"""inflation_32 = DataModel.GetObjectById(32);\n');
                        fprintf(Journal_File,'inflation_32.Suppressed = False;\n');
                        fprintf(Journal_File,'""")\n');
                        if Extraction_Checkbox_data.Value
                            fprintf(Journal_File,'model1.SendCommand(Language="Python",Command=\n');
                            fprintf(Journal_File,'"""inflation_32 = DataModel.GetObjectById(32);\n');
                            fprintf(Journal_File,'inflation_32.Suppressed = True;\n');
                            fprintf(Journal_File,'""")\n');
                        end
                        fprintf(Journal_File,'meshComponent1.Update(AllDependencies=True)\n');
                        fprintf(Journal_File,newline);
                        fprintf(Journal_File,'mshPath=r"%s%s.msh" \n', app.path, Journal_Number);
                        fprintf(Journal_File,'mshPath = mshPath.replace(''\\\\'', ''\\\\\\\\'')\n');
                        fprintf(Journal_File,'system = GetSystem(Name="SYS 1")\n');
                        fprintf(Journal_File,'mesh = system.GetContainer(ComponentName="Mesh")\n');
                        fprintf(Journal_File,'mesh.Edit()\n');
                        fprintf(Journal_File,'command2Send = """DS = WB.AppletList.Applet("DSApplet").App;\n');
                        fprintf(Journal_File,'var meshBranch = DS.Tree.FirstActiveBranch.MeshControlGroup;\n');
                        fprintf(Journal_File,'var filename = "%%s";\n');
                        fprintf(Journal_File,'DS.Script.doFileExport(filename);""" %%(mshPath)\n');
                        fprintf(Journal_File,'mesh.SendCommand(Command = command2Send)\n');
                        fprintf(Journal_File,'mesh.Exit()\n');
                        fprintf(Journal_File,newline);
                        fprintf(Journal_File,'####################### %s End #######################\n',Journal_Number);
                        fprintf(Journal_File,newline);
                    end

                    if Tip_data_dropdown.Value == "Type 2"

                        app.SB_Number = app.SB_Number+1;
                        app.SB_Position(i,:) = app.SB_Number;

                        match_B1 = cellfun(@(x) strcmp(x, 'B1 [mm]'), Table_Data_GUI(:,1));
                        type2t_B1 = Table_Data_GUI(match_B1, 2);
                        match_CR1 = cellfun(@(x) strcmp(x, 'CR1 [mm]'), Table_Data_GUI(:,1));
                        type2t_CR1 = Table_Data_GUI(match_CR1, 2);
                        match_S1 = cellfun(@(x) strcmp(x, 'S1 [mm]'), Table_Data_GUI(:,1));
                        type2t_S1 = Table_Data_GUI(match_S1, 2);
                        match_G1 = cellfun(@(x) strcmp(x, 'G1 [mm]'), Table_Data_GUI(:,1));
