                Tip_Seal_File_Path = fullfile(app.path, Tip_Journal_File_name);
                movefile('WB_Journal.txt', Tip_Seal_File_Path,'f');
                Work_count = Work_count+1;
            end
            app.Tip_MeshButton.Enable = 'On';
            fclose('all');
            if ~getappdata(status_bar, 'canceling')
                msgbox('저장 되었습니다.', '', 'info');
            end
            delete(status_bar);

            app.Brush_CR_R= CR_R_Tabel;
