        % Button pushed function: Tip_MeshButton
        function Tip_MeshButtonPushed(app, event)
            ans_path = {} ;
            Version_Check = app.CFX_Version_DropDown.Value;
            [Zero, Env] = system('set');
            Env = splitlines(Env);
            New_Env = {};
            Work =  app.End_Stage - app.Start_Stage;
            Work_count = 0;
            for i = 1:length(Env)
                Env_row = Env{i};
                if contains(Env_row, 'AWP_ROOT', 'IgnoreCase', true)
                    Env_Index = strfind(Env_row, '=');
                    Start_Index = Env_Index + 1;
                    Env_row = strtrim(Env_row(Start_Index:end));
                    New_Env{end+1,1} = Env_row;
                end
            end
            if Version_Check == "2022 R2"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v222')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2023 R1"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v231')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2023 R2"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v232')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2024 R1"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v242')
                        ans_path = New_Env_Line;
                    end
                end
            end
            status_bar = waitbar(0, 'Generating Mesh File...', 'Name', 'Blade Mesh File', 'CreateCancelBtn', 'setappdata(gcbf,''canceling'',1)');
            setappdata(status_bar, 'canceling', 0);
            for i = app.Start_Stage:app.End_Stage
                waitbar(Work_count/Work, status_bar, sprintf('Generating Mesh for Tip Seal %d...', i));
                Tip_Journal_File_Name_WB = sprintf('Tip_Seal_Stage%d.wbjn', i);
                Path_WB = """" + convertCharsToStrings(ans_path) + """" + "\Framework\bin\Win64\runwb2.exe" ;
                dos(Path_WB + " -B -R " + convertCharsToStrings(app.path) + Tip_Journal_File_Name_WB )
                if getappdata(status_bar, 'canceling')
                    msgbox('작업이 취소되었습니다.', '작업 취소', 'warn');
                    delete(status_bar);
                    return;
                end
                Work_count = Work_count+1;
            end
            delete(status_bar);

            Data_File_Folder = [app.path, 'Data File'];
            Data_File_Folder = replace(Data_File_Folder, "\", "/");

            for a = app.Start_Stage:app.End_Stage
                movefile(fullfile(app.path,sprintf('Tip_Seal_Stage%d.wbjn',a)), Data_File_Folder);
            end
            msgbox('저장 되었습니다.');
        end

        % Value changed function: Blade_Offset_Button
        function Blade_Offset_ButtonValueChanged(app, event)
            if app.Blade_Offset_Button.Value
                app.path = replace(app.path, "\", "/");
                defaultValue = {'Value'};
                answer = inputdlg('Blade Offset : [mm]', 'Blade Offset', [1 50], defaultValue);
                if isempty(answer)
                    return;
                end
                num = str2double(answer{1});
                if isnan(num)
                    errordlg('Blade Offset Value가 잘못 입력되었습니다.', 'Error');
                    return;
                end
                offset_value = num;
                fig = figure('Name', sprintf('Blade Offset Result (Offset: %.2f mm)', offset_value), 'Position', [100, 100, 1200, 800], 'MenuBar', 'none', 'ToolBar', 'none');
                tabgroup = uitabgroup(fig, 'Position', [0 0 1 1]);
                set(fig, 'WindowScrollWheelFcn', @(src, event) app.wheel_zoom_helper(src, event));
                status_bar = waitbar(0, 'Blade Offset 진행 중...', 'Name', 'Blade Offset Progress');
                setappdata(status_bar, 'canceling', 0);
                cancel_btn = uicontrol('Parent', status_bar, 'Style', 'pushbutton', 'String', 'Cancel', 'Position', [280 3 60 20], 'Callback', @(src,event) setappdata(status_bar, 'canceling', 1));
                try
                    for h = 1:app.Stage_Number
                        if getappdata(status_bar, 'canceling')
                            delete(status_bar);
                            delete(fig);
                            msgbox('작업이 취소되었습니다.', '작업 취소', 'warn');
                            return;
                        end
                        waitbar(h/app.Stage_Number, status_bar, sprintf('Stage %d/%d 처리 중...', h, app.Stage_Number));
                        tab = uitab(tabgroup, 'Title', sprintf('Stage %d', h));
                        nzl_filename = sprintf('nzl%02d_blade.curve', h);
                        [nzl_blade_points, nzl_offset_points] = app.process_blade_file_helper(nzl_filename, offset_value, app.path);
                        bck_filename = sprintf('bck%02d_blade.curve', h);
                        [bck_blade_points, bck_offset_points] = app.process_blade_file_helper(bck_filename, offset_value, app.path);

                        if app.Minus_CheckBox.Value == true
                            nzl_blade_points{1}(:,1) = -abs(nzl_blade_points{1}(:,1));
                        elseif app.Plus_CheckBox.Value == true
                            nzl_blade_points{1}(:,1) = abs(nzl_blade_points{1}(:,1));
                        end

                        ax1 = axes('Position', [0.01 0.05 0.49 0.9], 'Parent', tab);
                        plot(ax1, [nzl_blade_points{1}(:,1); nzl_blade_points{1}(1,1)], ...
                            [nzl_blade_points{1}(:,2); nzl_blade_points{1}(1,2)], 'k-', 'LineWidth', 1);
                        hold(ax1, 'on');
                        plot(ax1, [nzl_offset_points{1}(:,1); nzl_offset_points{1}(1,1)], ...
                            [nzl_offset_points{1}(:,2); nzl_offset_points{1}(1,2)], 'r-', 'LineWidth', 1);
                        title(ax1, sprintf('Stage %d - Nozzle Blade Offset', h), 'FontSize', 10);
                        axis(ax1, 'equal');
                        ax1.XAxis.TickLabels = {};
                        ax1.YAxis.TickLabels = {};
                        ax1.XAxis.TickLength = [0 0];
                        ax1.YAxis.TickLength = [0 0];
                        legend(ax1, 'Original Blade', 'Offset Blade', 'Location', 'southoutside', 'Orientation', 'horizontal');
                        hold(ax1, 'off');

                        if app.Minus_CheckBox.Value == true
                            bck_blade_points{1}(:,1) = -abs(bck_blade_points{1}(:,1));
                        elseif app.Plus_CheckBox.Value == true
                            bck_blade_points{1}(:,1) = abs(bck_blade_points{1}(:,1));
                        end

                        ax2 = axes('Position', [0.501 0.05 0.49 0.9], 'Parent', tab);
                        plot(ax2, [bck_blade_points{1}(:,1); bck_blade_points{1}(1,1)], ...
                            [bck_blade_points{1}(:,2); bck_blade_points{1}(1,2)], 'k-', 'LineWidth', 1);
                        hold(ax2, 'on');
                        plot(ax2, [bck_offset_points{1}(:,1); bck_offset_points{1}(1,1)], ...
                            [bck_offset_points{1}(:,2); bck_offset_points{1}(1,2)], 'r-', 'LineWidth', 1);
                        title(ax2, sprintf('Stage %d - Bucket Blade Offset', h), 'FontSize', 10);
                        axis(ax2, 'equal');
                        ax2.XAxis.TickLabels = {};
                        ax2.YAxis.TickLabels = {};
                        ax2.XAxis.TickLength = [0 0];
                        ax2.YAxis.TickLength = [0 0];
                        legend(ax2, 'Original Blade', 'Offset Blade', 'Location', 'southoutside', 'Orientation', 'horizontal');
                        hold(ax2, 'off');
                        zoom(ax1, 'on');
                        pan(ax1, 'on');
                        zoom(ax2, 'on');
                        pan(ax2, 'on');
                    end
                    delete(status_bar);
                    msgbox('저장 되었습니다.', '작업 완료', 'info');
                catch ME
                    delete(status_bar);
                    delete(fig);
                    errordlg(['오류 발생: ' ME.message], '오류');
                end
            end
        end

        % Button pushed function: Range_Button
        function Range_ButtonPushed(app, event)
            Def_Value = {'1', num2str(app.Stage_Number)};
            answer = inputdlg({'Start Stage', 'End Stage'},' ', [1 20; 1 20], Def_Value);
            if isempty(answer)
                return;
            end
            app.Start_Stage = str2double(answer{1});
            if isnan(app.Start_Stage)
                errordlg('잘못 입력되었습니다.', 'Error');
                return;
            end
            app.End_Stage = str2double(answer{2});
            if isnan(app.End_Stage)
                errordlg('잘못 입력되었습니다.', 'Error');
                return;
            end
            % 숫자 비교를 위해 문자열을 숫자로 변환
            start_num = str2double(answer{1});
            end_num = str2double(answer{2});
            if start_num > end_num
                errordlg('잘못 입력되었습니다.', 'Error');
                return;
            end
            if start_num == end_num
                app.Stage_Number_TextArea.Value = num2str(app.End_Stage);
                app.Pre_Stage_Number_TextArea.Value = num2str(app.End_Stage);
            else
                app.Stage_Number_TextArea.Value = app.Start_Stage + " ~ " + app.End_Stage;
                app.Pre_Stage_Number_TextArea.Value = app.Start_Stage + " ~ " + app.End_Stage;
            end
        end

        % Button pushed function: DataFileExportButton
        function DataFileExportButtonPushed(app, event)
            %status_window = msgbox('작업이 진행중입니다...','CFX-Pre Data File');
            %status_window = uiprogressdlg(fig,'Title','CFX-Pre','Message','작업이 진행중입니다...');
            app.Pre_Folder_Path = app.path;
            Pre_Path = replace(app.Pre_Folder_Path, "\", "/");
            if app.Blade_Only_CheckBox.Value
                if app.HP_CheckBox.Value == true
                    CFX_Pre_File = fopen('HP_CFX_Setup.txt','w');
                elseif app.IP_CheckBox.Value == true
                    CFX_Pre_File = fopen('IP_CFX_Setup.txt','w');
                end
                fprintf(CFX_Pre_File, ...
                    ['COMMAND FILE:\n' ...
                    '  CFX Pre Version = 22.2\n' ...
                    'END\n' ...
                    '\n' ...
                    '>load mode=new\n' ...
                    '> update\n' ...
                    '\n']);
                for i = app.Start_Stage:app.End_Stage
                    if app.HP_CheckBox.Value == true
                        fprintf(CFX_Pre_File, '> gtmImport filename=%sHP_nz_%02d.gtm, type=GTM, units=m, nameStrategy= Assembly\n',Pre_Path,i);
                    elseif app.IP_CheckBox.Value == true
                        fprintf(CFX_Pre_File, '> gtmImport filename=%sIP_nz_%02d.gtm, type=GTM, units=m, nameStrategy= Assembly\n',Pre_Path,i);
                    end
                end
                for i = app.Start_Stage:app.End_Stage
                    if app.HP_CheckBox.Value == true
                        fprintf(CFX_Pre_File, '> gtmImport filename=%sHP_bc_%02d.gtm, type=GTM, units=m, nameStrategy= Assembly\n',Pre_Path,i);
                    elseif app.IP_CheckBox.Value == true
                        fprintf(CFX_Pre_File, '> gtmImport filename=%sIP_bc_%02d.gtm, type=GTM, units=m, nameStrategy= Assembly\n',Pre_Path,i);
                    end
                end
                fprintf(CFX_Pre_File, ...
                    ['> update\n'...
                    '\n'...
                    'COMMAND FILE:\n' ...
                    '  CFX Pre Version = 22.2\n' ...
                    'END\n' ...
                    '\n' ...
                    'LIBRARY:\n' ...
                    '  CEL:\n' ...
                    '    &replace EXPRESSIONS:\n']);
                Outlet_Press = str2double(app.Pre_Setting_Outlet_Press_TextArea.Value);
                Inlet_Ent = str2double(app.Pre_Setting_Inlet_Ent_TextArea.Value);
                Inlet_Press = str2double(app.Pre_Setting_Inlet_Press_TextArea.Value);
                Inlet_Temp = str2double(app.Pre_Setting_Inlet_Temp_TextArea.Value);
                Turbine_RPM = str2double(app.Pre_Setting_RPM_TextArea.Value);
                fprintf(CFX_Pre_File,'      Bc 19 Outlet Ps = %d[MPa]\n', Outlet_Press);
                fprintf(CFX_Pre_File,'      Nz 01 Inlet Ht = %d[kJ/kg]\n', Inlet_Ent);
