            app.Pre_Setting_Inter01_Mass.Enable = 'on';
            app.Pre_Setting_Inter01_Mass_2.Enable = 'on';
            app.Pre_Setting_Inter01_Mass_TextArea.Enable = 'on';
            lines = strsplit(content, '\n');
            rpm_line = '';
            for i = 1:length(lines)
                if contains(lines{i}, 'r.p.m.')
                    rpm_line = lines{i};
                    break;
                end
            end
            if ~isempty(rpm_line)
                pattern = '(\d+)\s*\.\s*r\.p\.m\.';
                [match, ~] = regexp(rpm_line, pattern, 'tokens', 'match');
                if ~isempty(match)
                    rpm_value = str2double(match{1}{1});
                end
            end

            if app.Blade_Only_CheckBox.Value
                app.INTERSTAGEINLETLabel.Enable = 'off';
                app.Pre_Setting_Inter01_Mass_2.Enable = 'off';
                app.Pre_Setting_Inter01_Mass_TextArea.Enable = 'off';
                app.Pre_Setting_Inter01_Mass.Enable = 'off';
                try
                    app.EXTRACTIONLabel.Enable = 'off';
                    app.Pre_Setting_Extraction_Temp.Enable = 'off';
                    app.Pre_Setting_Extraction_Temp_2.Enable = 'off';
                    app.Pre_Setting_Extraction_Temp_TextArea.Enable = 'off';
                    app.Pre_Setting_Extraction_Mass.Enable = 'off';
                    app.Pre_Setting_Extraction_Mass_2.Enable = 'off';
                    app.Pre_Setting_Extraction_Mass_TextArea.Enable = 'off';
                catch
                end

            end
            app.Pre_Setting_RPM_TextArea.Value = num2str(rpm_value);
            app.Pre_Project_Name_TextArea.Value = app.Project_Name_TextArea.Value;
            app.DataFileExportButton.Enable = 'On';
            figure(app.UIFigure);
        end

        % Button pushed function: CFXPreRunButton
        function CFXPreRunButtonPushed(app, event)
            Pre_Path = replace(app.Pre_Folder_Path, "\", "/");
            app.path = replace(app.path, "\", "/");
            ans_path = {};
            Version_Check = app.CFX_Version_DropDown.Value;

            [Zero, Env] = system('set');
            Env = splitlines(Env);
            New_Env = {};
            for i = 1:length(Env)
                Env_row = Env{i};
                if contains(Env_row, 'AWP_ROOT', 'IgnoreCase', true)
                    Env_Index = strfind(Env_row, '=');
                    Start_Index = Env_Index + 1;
                    Env_row = strtrim(Env_row(Start_Index:end));
                    New_Env{end+1,1} = Env_row;
                end
            end
            if Version_Check == "2022 R2"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v222')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2023 R1"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v231')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2023 R2"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v232')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2024 R1"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v241')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2024 R2"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v242')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2025 R1"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v251')
                        ans_path = New_Env_Line;
                    end
                end
            end
            if Version_Check =="2025 R2"
                for i = 1:length(New_Env)
                    New_Env_Line = New_Env{i};
                    if contains(New_Env_Line, 'v252')
                        ans_path = New_Env_Line;
                    end
                end
            end

            all_stages_batch = [tempdir, 'run_CFX_Pre.bat'];
            fid_all = fopen(all_stages_batch, 'w');
            fprintf(fid_all, '@echo off\n');
            fprintf(fid_all, 'echo Starting CFX-Pre processing...\n');

            path_cfx = sprintf('%s\\CFX\\bin\\cfx5pre.exe', convertCharsToStrings(ans_path));
            path_cfx = replace(path_cfx, "\", "/");

            Pre_File_Name = sprintf('CFX_Setup.pre');
            cfx_pre_path= convertCharsToStrings(Pre_Path);
            session_full_path = fullfile(cfx_pre_path, Pre_File_Name);
            session_full_path = replace(session_full_path, '\', '/');

            fprintf(fid_all, '"%s" -batch %s\n', path_cfx,session_full_path);
            fprintf(fid_all, 'echo CFX-Pre Setting completed\n');

            fprintf(fid_all, 'exit\n');
            %fprintf(fid_all, 'pause\n');

            fclose(fid_all);

            cmd_all = sprintf('powershell -Command "Start-Process \"%s\" -Verb RunAs -Wait"', all_stages_batch);
            disp('Starting TurboGrid processing for all stages...');
            system(cmd_all);

            msgbox('저장 되었습니다.', '작업 완료', 'info');

            Data_File_Folder = [app.path, 'Data File'];
            Data_File_Folder = replace(Data_File_Folder, "\", "/");

            files_to_move = {
					sprintf('HP_CFX_Setup.txt');
                    sprintf('HP_Domain_fluid_NB.txt');
                    sprintf('HP_Domain_Honeycomb.txt');
                    sprintf('HP_Domain_interstage.txt');
                    sprintf('HP_Domain_Rotor_Stator.txt');
					sprintf('HP_Domain_Swirl_Brake.txt');
					sprintf('HP_HC_mesh_del.txt');
