        % Button pushed function: Interstage_FileButton
        function Interstage_FileButtonPushed(app, event)
            [Packing_Seal_file, app.Packing_Seal_Path] = uigetfile({'*.xls;*.xlsx;*.xlsm;','Excel File(*.xls,*.xlsx,*.xlsm)';}, 'Select File','pwd');
            if isequal(Packing_Seal_file, 0)
                uialert(app.UIFigure, '파일 선택이 취소되었습니다.', 'File Selection Cancelled');
                return;
            end
            Packing_Seal_file_path = fullfile(app.Packing_Seal_Path, Packing_Seal_file);
            app.Interstage_Save_File_Path_TextArea.Value = Packing_Seal_file_path;
            app.Tip_Save_File_Path_TextArea.Value = Packing_Seal_file_path;
            Packing_Seal_Range = "AY4:CQ99";
            Packing_Seal_Data_Table = readtable(Packing_Seal_file_path, 'Sheet', 'sht1', 'range', Packing_Seal_Range);
            hp_rows = contains(Packing_Seal_Data_Table{:,1}, 'HP');
            ip_rows = contains(Packing_Seal_Data_Table{:,1}, 'IP');
            hp_data = Packing_Seal_Data_Table(hp_rows,:);
            ip_data = Packing_Seal_Data_Table(ip_rows,:);
            hp_interstage_data = hp_data(:, 6:21);
