    % Component initialization
    methods (Access = private)

        % Helper function for mouse wheel zoom
        function wheel_zoom_helper(app, ~, eventdata)
            current_axis = gca;
            if eventdata.VerticalScrollCount > 0
                zoom(current_axis, 1/app.ZOOM_FACTOR);
            elseif eventdata.VerticalScrollCount < 0
                zoom(current_axis, app.ZOOM_FACTOR);
            end
        end

        % Helper function to process blade file with offset
        function [blade_points, offset_points] = process_blade_file_helper(app, filename, offset_value, path)
            Blade_File_Path = fullfile(path, filename);
            offset_File_Name = strrep(filename, '.curve', '_offset.curve');
            offset_File_Path = fullfile(path, offset_File_Name);
            fileContent = fileread(Blade_File_Path);
            sections = strsplit(fileContent, '#');
            fid = fopen(offset_File_Path, 'w');
            blade_points = cell(1, length(sections)-1);
            offset_points = cell(1, length(sections)-1);
            for k = 2:length(sections)
                section = strtrim(sections{k});
                if ~isempty(section)
                    fprintf(fid, '#\n');
                    data = textscan(section, '%f %f %f', 'Delimiter', ' ', 'MultipleDelimsAsOne', true);
                    blade_points{k-1} = [data{1}, data{2}];
                    z_values = data{3};
                    blade_points{k-1} = [blade_points{k-1}; blade_points{k-1}(1,:)];
                    z_values = [z_values; z_values(1)];

                    if all(data{1} > 0)
                        app.Flip_Offset = -1;
                    elseif all(data{1} < 0)
                        app.Flip_Offset = 1;
                    end

                    offset_distance = offset_value * -1 * app.Flip_Offset;
                    offset_points{k-1} = zeros(size(blade_points{k-1}));
                    for i = 1:size(blade_points{k-1}, 1)-1
                        if i == 1
                            dx = blade_points{k-1}(2, 1) - blade_points{k-1}(1, 1);
                            dy = blade_points{k-1}(2, 2) - blade_points{k-1}(1, 2);
                        elseif i == size(blade_points{k-1}, 1)-1
                            dx = blade_points{k-1}(end-1, 1) - blade_points{k-1}(end-2, 1);
                            dy = blade_points{k-1}(end-1, 2) - blade_points{k-1}(end-2, 2);
                        else
                            dx1 = blade_points{k-1}(i, 1) - blade_points{k-1}(i-1, 1);
                            dy1 = blade_points{k-1}(i, 2) - blade_points{k-1}(i-1, 2);
                            dx2 = blade_points{k-1}(i+1, 1) - blade_points{k-1}(i, 1);
                            dy2 = blade_points{k-1}(i+1, 2) - blade_points{k-1}(i, 2);
                            dx = (dx1 + dx2) / 2;
                            dy = (dy1 + dy2) / 2;
                        end
                        segment_length = sqrt(dx^2 + dy^2);
                        nx = -dy / segment_length;
                        ny = dx / segment_length;
                        if strcmp(filename(1:length(app.NOZZLE_PREFIX)), app.NOZZLE_PREFIX)
                            offset_points{k-1}(i, 1) = blade_points{k-1}(i, 1) - offset_distance * nx;
                            offset_points{k-1}(i, 2) = blade_points{k-1}(i, 2) - offset_distance * ny;
                        else
                            offset_points{k-1}(i, 1) = blade_points{k-1}(i, 1) + offset_distance * nx;
                            offset_points{k-1}(i, 2) = blade_points{k-1}(i, 2) + offset_distance * ny;
                        end
                    end
                    offset_points{k-1}(end,:) = offset_points{k-1}(1,:);
                    for z = 1:size(offset_points{k-1}, 1)
                        if app.Minus_CheckBox.Value == true
                            offset_points{k-1}(z,1) = -abs(offset_points{k-1}(z,1));
                        elseif app.Plus_CheckBox.Value == true
                            offset_points{k-1}(z,1) = abs(offset_points{k-1}(z,1));
                        end
                        format_str = sprintf('  %%.%df    %%.%df    %%.%df  \\n', app.CURVE_PRECISION, app.CURVE_PRECISION, app.CURVE_PRECISION);
                        fprintf(fid, format_str, offset_points{k-1}(z,1), offset_points{k-1}(z,2), z_values(z));
                    end
                end
            end
            fclose(fid);
        end

        % Create UIFigure and components
        function createComponents(app)

            % Get the file path for locating images
            pathToMLAPP = fileparts(mfilename('fullpath'));

            % Create UIFigure and hide until all components are created
            app.UIFigure = uifigure('Visible', 'off');
            app.UIFigure.Position = [100 100 1035 884];
            app.UIFigure.Name = 'MATLAB App';
            app.UIFigure.CloseRequestFcn = createCallbackFcn(app, @UIFigureCloseRequest, true);
            app.UIFigure.Scrollable = 'on';

            % Create TabGroup2
            app.TabGroup2 = uitabgroup(app.UIFigure);
            app.TabGroup2.Position = [1 1 1036 886];

            % Create GeometryTab
            app.GeometryTab = uitab(app.TabGroup2);
            app.GeometryTab.Title = 'Geometry';

            % Create TabGroup
            app.TabGroup = uitabgroup(app.GeometryTab);
            app.TabGroup.Position = [0 1 1035 862];

            % Create TurbineBladeTab
            app.TurbineBladeTab = uitab(app.TabGroup);
            app.TurbineBladeTab.Title = 'Turbine Blade';

            % Create Design_File_Path_Group
            app.Design_File_Path_Group = uibuttongroup(app.TurbineBladeTab);
            app.Design_File_Path_Group.Position = [10 728 370 100];

            % Create BladeDesignFilePathLabel
            app.BladeDesignFilePathLabel = uilabel(app.Design_File_Path_Group);
            app.BladeDesignFilePathLabel.FontSize = 16;
            app.BladeDesignFilePathLabel.FontWeight = 'bold';
            app.BladeDesignFilePathLabel.Position = [14 69 178 22];
            app.BladeDesignFilePathLabel.Text = 'Blade Design File Path';

            % Create Design_File_Path_TextArea
            app.Design_File_Path_TextArea = uitextarea(app.Design_File_Path_Group);
            app.Design_File_Path_TextArea.ValueChangedFcn = createCallbackFcn(app, @Design_File_Path_TextAreaValueChanged, true);
            app.Design_File_Path_TextArea.ValueChangingFcn = createCallbackFcn(app, @Design_File_Path_TextAreaValueChanging, true);
            app.Design_File_Path_TextArea.Tag = 'File_Path';
            app.Design_File_Path_TextArea.Editable = 'off';
